+/// A log handler that records each log event it receives, including the error associated
+/// with the event and the caller location, exactly as forwarded by the logger.
+private final class RecordingErrorHandler: LogHandler, @unchecked Sendable {
+    struct RecordedEvent {
+        let level: Logger.Level
+        let message: String
+        let error: (any Error)?
+        let file: String
+        let function: String
+        let line: UInt
+    }
+
+    final class EventRecorder: @unchecked Sendable {
+        private let lock = NSLock()
+        private var recordedEvents: [RecordedEvent] = []
+
+        func record(_ event: RecordedEvent) {
+            self.lock.lock()
+            self.recordedEvents.append(event)
+            self.lock.unlock()
+        }
+
+        var entries: [RecordedEvent] {
+            self.lock.lock()
+            defer { self.lock.unlock() }
+            return self.recordedEvents
+        }
+    }
+
+    let recorder: EventRecorder
+    var logLevel: Logger.Level = .trace
+    var metadata: Logger.Metadata = [:]
+    var metadataProvider: Logger.MetadataProvider? = nil
+
+    init(recorder: EventRecorder) {
+        self.recorder = recorder
+    }
+
+    func log(event: LogEvent) {
+        self.recorder.record(
+            RecordedEvent(
+                level: event.level,
+                message: event.message.description,
+                error: event.error,
+                file: event.file,
+                function: event.function,
+                line: event.line
+            )
+        )
+    }
+
+    subscript(metadataKey key: String) -> Logger.Metadata.Value? {
+        get { self.metadata[key] }
+        set { self.metadata[key] = newValue }
+    }
+}
+
+private final class ReferenceError: Error, @unchecked Sendable {
+    let message: String
+
+    init(message: String) {
+        self.message = message
+    }
+}
