+import 'dart:io';
+
+import 'package:noports_core/src/common/relay_latency_checker.dart';
+import 'package:test/test.dart';
+
+void main() {
+  group('RelayLatencyChecker.measureLatencies', () {
+    test('empty rvServers returns empty map', () async {
+      final result = await RelayLatencyChecker.measureLatencies({});
+      expect(result, isEmpty);
+    });
+
+    test('missing ipaddr → -1', () async {
+      final result = await RelayLatencyChecker.measureLatencies({
+        '@rv_am': {'port': 443},
+      });
+      expect(result['@rv_am'], -1);
+    });
+
+    test('missing port → -1', () async {
+      final result = await RelayLatencyChecker.measureLatencies({
+        '@rv_am': {'ipaddr': '1.2.3.4'},
+      });
+      expect(result['@rv_am'], -1);
+    });
+
+    test('both ipaddr and port missing → -1', () async {
+      final result = await RelayLatencyChecker.measureLatencies({
+        '@rv_am': <String, dynamic>{},
+      });
+      expect(result['@rv_am'], -1);
+    });
+
+    test('connection refused → -1', () async {
+      // Bind then close a listener to obtain a definitely-free port; a
+      // connection attempt to it is refused immediately.
+      final temp = await ServerSocket.bind('127.0.0.1', 0);
+      final closedPort = temp.port;
+      await temp.close();
+
+      final result = await RelayLatencyChecker.measureLatencies({
+        '@rv_am': {'ipaddr': '127.0.0.1', 'port': closedPort},
+      });
+      expect(result['@rv_am'], -1);
+    });
+
+    test('reachable host → latency ≥ 0', () async {
+      final listener = await ServerSocket.bind('127.0.0.1', 0);
+      addTearDown(() async {
+        await listener.close();
+      });
+
+      final result = await RelayLatencyChecker.measureLatencies({
+        '@rv_am': {'ipaddr': '127.0.0.1', 'port': listener.port},
+      });
+      expect(result['@rv_am'], greaterThanOrEqualTo(0));
+    });
+
+    test('mixed reachable and unreachable hosts', () async {
+      final listener = await ServerSocket.bind('127.0.0.1', 0);
+      addTearDown(() async {
+        await listener.close();
+      });
+
+      final temp = await ServerSocket.bind('127.0.0.1', 0);
+      final closedPort = temp.port;
+      await temp.close();
+
+      final result = await RelayLatencyChecker.measureLatencies({
+        '@rv_am': {'ipaddr': '127.0.0.1', 'port': listener.port},
+        '@rv_eu': {'ipaddr': '127.0.0.1', 'port': closedPort}, // refused
+      });
+      expect(result.keys, containsAll(['@rv_am', '@rv_eu']));
+      expect(result['@rv_am'], greaterThanOrEqualTo(0));
+      expect(result['@rv_eu'], -1);
+    });
+
+    test('all keys present in result regardless of outcome', () async {
+      final temp = await ServerSocket.bind('127.0.0.1', 0);
+      final closedPort = temp.port;
+      await temp.close();
+
+      final result = await RelayLatencyChecker.measureLatencies({
+        '@rv_am': {'port': 443}, // missing ipaddr → -1
+        '@rv_eu': {'ipaddr': '127.0.0.1', 'port': closedPort}, // refused → -1
+      });
+      expect(result.keys, containsAll(['@rv_am', '@rv_eu']));
+      expect(result['@rv_am'], -1);
+      expect(result['@rv_eu'], -1);
+    });
+  });
+}
diff --git a/packages/dart/noports_core/test/sshnp/relay_selector_test.dart b/packages/dart/noports_core/test/sshnp/relay_selector_test.dart
new file mode 100644
index 000000000..15f18152f
--- /dev/null
+++ b/packages/dart/noports_core/test/sshnp/relay_selector_test.dart
@@ -0,0 +1,437 @@
+import 'dart:async';
+import 'dart:convert';
+import 'dart:io';
+
+import 'package:at_client/at_client.dart';
+import 'package:mocktail/mocktail.dart';
+import 'package:noports_core/src/common/default_args.dart';
+import 'package:noports_core/src/common/relay_selector.dart';
+import 'package:noports_core/srvd.dart';
+import 'package:test/test.dart';
+
+import 'sshnp_mocks.dart';
+
+/// Shared bound for automatic relay selection in this suite. It turns any
+/// regression into unbounded waiting (a hang) into a decisive test failure
+/// while comfortably exceeding the contract's documented completion window
+/// and keeping bounded-detection and fallback runs fast in CI.
+const boundedSelection = Duration(seconds: 30);
+
+// ---------------------------------------------------------------------------
+// Helpers
+// ---------------------------------------------------------------------------
+
+/// Delivers [notification] repeatedly on a broadcast stream until the
+/// subscribing code has consumed it (i.e. cancelled its subscription) or
+/// [timeout] elapses. Automatic relay selection subscribes before it sends
+/// its requests, but a just-in-time registered listener may not be attached
+/// in the very same event-loop turn in which a mocked request fires.
+Future<void> deliverUntilConsumed(
+  StreamController<AtNotification> stream,
+  AtNotification notification, {
+  Duration timeout = const Duration(seconds: 10),
+}) async {
+  final deadline = DateTime.now().add(timeout);
+  while (stream.hasListener) {
+    stream.add(notification);
+    if (DateTime.now().isAfter(deadline)) return;
+    await Future.delayed(const Duration(milliseconds: 25));
+  }
+}
+
+/// In-memory stand-in for the client-side messaging layer used by automatic
+/// relay selection. The code under test publishes requests through its
+/// current AtClient's notification service and receives responses on a
+/// subscription stream; the harness collects the published requests and
+/// feeds responses back. Producers follow the response convention used on
+/// the wire: a response's `from` field identifies the responder and its key
+/// carries the response topic before the requester's atsign.
+class RelaySelectionHarness {
+  final StreamController<AtNotification> inbound =
+      StreamController<AtNotification>.broadcast();
+
+  AtNotification response({
+    required String topic,
+    required String responderAtSign,
+    required String clientAtSign,
+    required String payloadValue,
+  }) => AtNotification(
+    'notification-${DateTime.now().microsecondsSinceEpoch}',
+    '$responderAtSign:$topic.${DefaultArgs.namespace}$clientAtSign',
+    responderAtSign,
+    clientAtSign,
+    DateTime.now().millisecondsSinceEpoch,
+    'update',
+    false,
+    value: payloadValue,
+    operation: 'update',
+  );
+
+  /// Binds a real loopback listener per relay atsign so the selection
+  /// round's genuine client-side latency probe sees every relay as
+  /// reachable and fast (~0ms each). Their measured latencies are
+  /// effectively equal, which makes any device-reported latencies the
+  /// deciding factor in a combined calculation.
+  Future<Map<String, Map<String, dynamic>>> localRelayIps(
+    List<String> rvs,
+  ) async {
+    final map = <String, Map<String, dynamic>>{};
+    for (final rv in rvs) {
+      final listener = await ServerSocket.bind('127.0.0.1', 0);
+      addTearDown(() async => listener.close());
+      map[rv] = {'ipaddr': '127.0.0.1', 'port': listener.port};
+    }
+    return map;
+  }
+}
+
+void main() {
+  group('RelaySelector', () {
+    const clientAtSign = '@alice';
+    const sshnpdAtSign = '@bob';
+    const device = 'test_device';
+    const rootDomain = 'root.atsign.org';
+
+    late MockAtClient mockAtClient;
+    late MockNotificationService mockNotificationService;
+    late RelaySelectionHarness harness;
+    late RelaySelector rs;
+
+    /// Chain of handlers consulted for each outgoing publish; the first
+    /// non-null result wins.
+    List<Future<NotificationResult?> Function(NotificationParams)>
+    requestHandlers = [];
+
+    setUpAll(() {
+      registerFallbackValue(AtKey());
+      registerFallbackValue(const Duration(seconds: 10));
+      registerFallbackValue(AtNotification.empty());
+      registerFallbackValue(NotificationParams.forUpdate(AtKey()));
+    });
+
+    setUp(() {
+      requestHandlers = [];
+      mockAtClient = MockAtClient();
+      mockNotificationService = MockNotificationService();
+      harness = RelaySelectionHarness();
+
+      when(() => mockAtClient.getCurrentAtSign()).thenReturn(clientAtSign);
+      when(
+        () => mockAtClient.notificationService,
+      ).thenReturn(mockNotificationService);
+
+      // Every subscription, whatever its filter, is handed the shared
+      // broadcast inbox, so no assumptions about how the code under test
+      // partitions its subscriptions are required.
+      when(
+        () => mockNotificationService.subscribe(
+          regex: any(named: 'regex'),
+          shouldDecrypt: any(named: 'shouldDecrypt'),
+        ),
+      ).thenAnswer((_) => harness.inbound.stream);
+
+      // Default request handling: outgoing publishes are accepted and
+      // answered by shape (see [answerRound]).
+      when(
+        () => mockNotificationService.notify(
+          any(),
+          checkForFinalDeliveryStatus: any(named: 'checkForFinalDeliveryStatus'),
+          waitForFinalDeliveryStatus: any(named: 'waitForFinalDeliveryStatus'),
+          onSuccess: any(named: 'onSuccess'),
+          onError: any(named: 'onError'),
+        ),
+      ).thenAnswer((i) async {
+        final params = i.positionalArguments[0] as NotificationParams;
+        for (final handler in requestHandlers) {
+          final result = await handler(params);
+          if (result != null) return result;
+        }
+        return NotificationResult()
+          ..notificationStatusEnum = NotificationStatusEnum.delivered;
+      });
+
+      rs = RelaySelector(
+        atClient: mockAtClient,
+        clientAtSign: clientAtSign,
+        sshnpdAtSign: sshnpdAtSign,
+        device: device,
+        rootDomain: rootDomain,
+      );
+    });
+
+
+    /// Answers both phases of one selection round. Every address-resolution
+    /// request whose concern (the payload's `items` list) matches a relay
+    /// address enquiry gets the response for that relay from [ipMap], unless
+    /// the relay is in [skipDiscoverFor]. Every device relay-latency request
+    /// (its payload maps relay atsigns to connection details) gets the
+    /// encoded [deviceLatencies] response; when [deviceLatencies] is null
+    /// and [onDevicePhase] is not provided, the device stays silent.
+    void answerRound({
+      Map<String, Map<String, dynamic>> ipMap = const {},
+      Map<String, int>? deviceLatencies,
+      Set<String> skipDiscoverFor = const {},
+      void Function()? onDevicePhase,
+    }) {
+      requestHandlers.add((params) async {
+        final value = params.value;
+        if (value == null) return null;
+        final dynamic decoded;
+        try {
+          decoded = jsonDecode(value);
+        } catch (_) {
+          return null;
+        }
+        if (decoded is Map && decoded['items'] is List) {
+          // Relay address-resolution request.
+          final rv = params.atKey.sharedWith ?? '';
+          final ipInfo = ipMap[rv];
+          if (ipInfo != null && !skipDiscoverFor.contains(rv)) {
+            unawaited(
+              deliverUntilConsumed(
+                harness.inbound,
+                harness.response(
+                  topic: 'discover_response.${Srvd.namespace}',
+                  responderAtSign: rv,
+                  clientAtSign: clientAtSign,
+                  payloadValue: jsonEncode(ipInfo),
+                ),
+              ),
+            );
+          }
+          return NotificationResult()
+            ..notificationStatusEnum = NotificationStatusEnum.delivered;
+        }
+        if (decoded is Map &&
+            decoded.values.every((v) => v is Map && v['ipaddr'] is String)) {
+          // Device relay-latency request.
+          if (onDevicePhase != null) {
+            onDevicePhase();
+          } else if (deviceLatencies != null) {
+            unawaited(
+              deliverUntilConsumed(
+                harness.inbound,
+                harness.response(
+                  topic: 'relay_latency_response.$device',
+                  responderAtSign: sshnpdAtSign,
+                  clientAtSign: clientAtSign,
+                  payloadValue: jsonEncode(deviceLatencies),
+                ),
+              ),
+            );
+          }
+          return NotificationResult()
+            ..notificationStatusEnum = NotificationStatusEnum.delivered;
+        }
+        return null;
+      });
+    }
+
+    // ---------------------------------------------------------------------
+    // constructor
+    // ---------------------------------------------------------------------
+    group('constructor', () {
+      test('builds rvServerListUrl from plain domain', () {
+        expect(
+          rs.rvServerListUrl,
+          'https://atsign-foundation.github.io/noports/root.atsign.org/standard_relays.json',
+        );
+      });
+
+      test('strips proxy: prefix from rootDomain', () {
+        final withProxy = RelaySelector(
+          atClient: mockAtClient,
+          clientAtSign: clientAtSign,
+          sshnpdAtSign: sshnpdAtSign,
+          device: device,
+          rootDomain: 'proxy:proxy0001.atsign.org',
+        );
+        expect(
+          withProxy.rvServerListUrl,
+          'https://atsign-foundation.github.io/noports/proxy0001.atsign.org/standard_relays.json',
+        );
+      });
+    });
+
+    // ---------------------------------------------------------------------
+    // selectBestRelay (behavioral; black-box via the in-memory harness)
+    //
+    // The group-level [boundedSelection] timeout governs every case here;
+    // it is generous enough that flaky double-reporting of a timed-out case
+    // (package:test re-points a pending late error at the then-current case)
+    // cannot push a healthy run past any outer harness budget.
+    // ---------------------------------------------------------------------
+    group('selectBestRelay', () {
+      // Device detail passed to the selector; suffixed so its latency
+      // response topic is also its real response topic
+      // ('<topic>.sshnp<client>').
+      const device = 'test_device.sshnp';
+      const rv1 = '@rv_am';
+      const rv2 = '@rv_eu';
+
+      test('selects RV with lowest combined average latency', () async {
+        // Real loopback listeners keep client-side latencies ~0 for both
+        // RVs, so the device-reported latencies decide the winner.
+        final ipMap = await harness.localRelayIps([rv1, rv2]);
+        answerRound(ipMap: ipMap, deviceLatencies: {rv1: 10, rv2: 100});
+
+        final result = await rs.selectBestRelay(
+          rvAtSigns: [rv1.toAtsign(), rv2.toAtsign()],
+        );
+        expect(result, rv1);
+      });
+
+      test('throws when no RV IPs resolve', () async {
+        // Nothing answers address resolution → the selector must give up
+        // on that phase rather than hang forever.
+        await expectLater(
+          rs.selectBestRelay(rvAtSigns: [rv1.toAtsign()]),
+          throwsA(anything),
+        );
+      });
+
+      test('partial IP resolution — selects best from resolved RVs only',
+          () async {
+        // rv1 never answers address resolution; rv2 responds normally and
+        // is the only candidate left.
+        final ipMap = await harness.localRelayIps([rv1, rv2]);
+        answerRound(
+          ipMap: ipMap,
+          deviceLatencies: {rv2: 30},
+          skipDiscoverFor: {rv1},
+        );
+
+        final result = await rs.selectBestRelay(
+          rvAtSigns: [rv1.toAtsign(), rv2.toAtsign()],
+        );
+        expect(result, rv2);
+      });
+
+      test('single resolved RV is returned', () async {
+        final ipMap = await harness.localRelayIps([rv1]);
+        answerRound(ipMap: ipMap, deviceLatencies: {rv1: 15});
+
+        final result = await rs.selectBestRelay(rvAtSigns: [rv1.toAtsign()]);
+        expect(result, rv1);
+      });
+
+      test('latency tie — returns one of the tied RVs', () async {
+        final ipMap = await harness.localRelayIps([rv1, rv2]);
+        answerRound(ipMap: ipMap, deviceLatencies: {rv1: 50, rv2: 50});
+
+        final result = await rs.selectBestRelay(
+          rvAtSigns: [rv1.toAtsign(), rv2.toAtsign()],
+        );
+        // Both RVs are equally good; any pick of a tied RV satisfies the
+        // selection contract.
+        expect(result, isIn([rv1, rv2]));
+      });
+
+      // ---------------------------------------------------------------------
+      // device-latency fallback (issue #2752)
+      //
+      // When usable device-reported relay latencies are unavailable,
+      // automatic relay selection must complete within a bounded time using
+      // client-side latencies alone: it must neither hang nor fail. These
+      // cases run under the enclosing group's completion bound, which
+      // expresses the documented bounded-completion contract without
+      // mandating any internal timeout mechanism or value.
+      // ---------------------------------------------------------------------
+      group('device-latency fallback', () {
+        test(
+          'device never responds → completes via client-only latency',
+          () async {
+            // Both RVs are real loopback listeners (reachable, ~0ms for the
+            // client probe). The device stays silent, simulating a relay
+            // daemon that never reports its own latencies.
+            final ipMap = await harness.localRelayIps([rv1, rv2]);
+            answerRound(ipMap: ipMap);
+
+            final result = await rs.selectBestRelay(
+              rvAtSigns: [rv1.toAtsign(), rv2.toAtsign()],
+            );
+            // Client-only fallback: both relays are reachable, so either one
+            // is a valid pick; the critical behaviors are that selection
+            // completes at all and picks a reachable relay.
+            expect(result, isIn([rv1, rv2]));
+          },
+        );
+
+        test(
+          'device response unusable → completes via client-only latency',
+          () async {
+            final ipMap = await harness.localRelayIps([rv1, rv2]);
+            answerRound(
+              ipMap: ipMap,
+              onDevicePhase: () {
+                harness.inbound.add(
+                  harness.response(
+                    topic: 'relay_latency_response.$device',
+                    responderAtSign: sshnpdAtSign,
+                    clientAtSign: clientAtSign,
+                    payloadValue: 'not-valid-json{{{',
+                  ),
+                );
+              },
+            );
+
+            final result = await rs.selectBestRelay(
+              rvAtSigns: [rv1.toAtsign(), rv2.toAtsign()],
+            );
+            expect(result, isIn([rv1, rv2]));
+          },
+        );
+
+        test(
+          'silent device surfaces no timeout error (issue #2752 regression guard)',
+          () async {
+            final ipMap = await harness.localRelayIps([rv1, rv2]);
+            answerRound(ipMap: ipMap);
+
+            // A lapse back into unbounded waiting either throws a timeout
+            // error or hangs past the enclosing group's bound, which turns
+            // a hang into a decisive failure.
+            await expectLater(
+              rs.selectBestRelay(rvAtSigns: [rv1.toAtsign(), rv2.toAtsign()]),
+              completion(isIn([rv1, rv2])),
+            );
+          },
+        );
+
+        test(
+          'device-phase publish never completes → selection still completes',
+          () async {
+            // Even if publishing the device latency request is never settled
+            // by the messaging layer (e.g. stalled delivery retries),
+            // selection must still complete via client-only latencies.
+            final ipMap = await harness.localRelayIps([rv1, rv2]);
+            answerRound(ipMap: ipMap);
+            requestHandlers.add((params) {
+              final value = params.value;
+              if (value == null) return Future.value(null);
+              dynamic decoded;
+              try {
+                decoded = jsonDecode(value);
+              } catch (_) {
+                return Future.value(null);
+              }
+              if (decoded is Map &&
+                  decoded.values.every(
+                    (v) => v is Map && v['ipaddr'] is String,
+                  )) {
+                // Device relay-latency request → never settled.
+                return Completer<NotificationResult>().future;
+              }
+              return Future.value(null);
+            });
+
+            await expectLater(
+              rs.selectBestRelay(rvAtSigns: [rv1.toAtsign(), rv2.toAtsign()]),
+              completion(isIn([rv1, rv2])),
+            );
+          },
+        );
+      });
+    }, timeout: const Timeout(boundedSelection));
+  });
+}
diff --git a/packages/dart/noports_core/test/sshnpd/relay_latency_request_test.dart b/packages/dart/noports_core/test/sshnpd/relay_latency_request_test.dart
new file mode 100644
index 000000000..b166be761
--- /dev/null
+++ b/packages/dart/noports_core/test/sshnpd/relay_latency_request_test.dart
@@ -0,0 +1,176 @@
+import 'dart:convert';
+import 'dart:io';
+
+import 'package:at_client/at_client.dart';
+import 'package:mocktail/mocktail.dart';
+import 'package:noports_core/src/common/default_args.dart';
+import 'package:noports_core/src/common/types.dart';
+import 'package:noports_core/src/sshnpd/sshnpd_impl.dart';
+import 'package:test/test.dart';
+
+class MockAtClient extends Mock implements AtClient {}
+
+class MockNotificationService extends Mock implements NotificationService {}
+
+class FakeNotificationParams extends Fake implements NotificationParams {}
+
+class FakeAtKey extends Fake implements AtKey {}
+
+void main() {
+  group('sshnpd handles relay_latency_request', () {
+    const String clientAtsign = '@client';
+    const String deviceAtsign = '@testdevice';
+    const String device = 'testdevice';
+
+    late MockAtClient mockAtClient;
+    late MockNotificationService mockNotificationService;
+    late SshnpdImpl sshnpd;
+    late List<NotificationParams> sentNotifications;
+
+    setUp(() {
+      registerFallbackValue(FakeNotificationParams());
+      registerFallbackValue(FakeAtKey());
+
+      mockAtClient = MockAtClient();
+      mockNotificationService = MockNotificationService();
+      sentNotifications = [];
+
+      when(() => mockAtClient.getCurrentAtSign()).thenReturn(deviceAtsign);
+      when(
+        () => mockAtClient.notificationService,
+      ).thenReturn(mockNotificationService);
+
+      // Capture every outgoing notify call for assertions.
+      when(
+        () => mockNotificationService.notify(
+          any(),
+          checkForFinalDeliveryStatus: any(
+            named: 'checkForFinalDeliveryStatus',
+          ),
+          waitForFinalDeliveryStatus: any(named: 'waitForFinalDeliveryStatus'),
+          onSuccess: any(named: 'onSuccess'),
+          onError: any(named: 'onError'),
+          onSentToSecondary: any(named: 'onSentToSecondary'),
+        ),
+      ).thenAnswer((Invocation i) async {
+        sentNotifications.add(i.positionalArguments[0] as NotificationParams);
+        return NotificationResult()
+          ..notificationStatusEnum = NotificationStatusEnum.delivered;
+      });
+
+      // clientAtsign is registered as a manager so authCheck short-circuits
+      // to "authorized" without hitting any policy logic.
+      sshnpd = SshnpdImpl(
+        atClient: mockAtClient,
+        username: 'testuser',
+        homeDirectory: '/home/testuser',
+        device: device,
+        managerAtsigns: [clientAtsign],
+        policyManagerAtsign: null,
+        sshClient: SupportedSshClient.openssh,
+        makeDeviceInfoVisible: false,
+        addSshPublicKeys: false,
+        localSshdPort: 22,
+        sshPublicKeyPermissions: '',
+        ephemeralPermissions: '',
+        sshAlgorithm: SupportedSshAlgorithm.rsa,
+        deviceGroup: 'default',
+        version: '1.0.0',
+        permitOpen: ['*:*'],
+        strict: false,
+      );
+    });
+
+    // Builds the relay-latency request payload as it arrives at the daemon.
+    AtNotification latencyRequest({required String id, String? value}) {
+      return AtNotification(
+        id,
+        '$deviceAtsign:relay_latency_request.$device.${DefaultArgs.namespace}$clientAtsign',
+        clientAtsign, // from
+        deviceAtsign, // to
+        123,
+        'key',
+        true,
+      )..value = value;
+    }
+
+    Map<String, dynamic> decodeLatencyResponse(NotificationParams n) {
+      expect(n.atKey.key, 'relay_latency_response.$device');
+      expect(n.atKey.sharedWith, clientAtsign);
+      expect(n.atKey.namespace, DefaultArgs.namespace);
+      return jsonDecode(n.value!) as Map<String, dynamic>;
+    }
+
+    test('returns positive latency for a reachable RV', () async {
+      // Real local listener — the probe should succeed quickly with latency ≥ 0.
+      final listener = await ServerSocket.bind('127.0.0.1', 0);
+      addTearDown(() async {
+        await listener.close();
+      });
+
+      await sshnpd.clientRequestNotificationHandler(
+        latencyRequest(
+          id: 'aaaa1111-0000-0000-0000-000000000001',
+          value: jsonEncode({
+            '@rv1': {'ipaddr': '127.0.0.1', 'port': listener.port},
+          }),
+        ),
+      );
+
+      expect(sentNotifications, hasLength(1));
+      final response = decodeLatencyResponse(sentNotifications.single);
+      expect(response.containsKey('@rv1'), isTrue);
+      expect(response['@rv1'], isA<int>());
+      expect(response['@rv1'], greaterThanOrEqualTo(0));
+    });
+
+    test('returns -1 for an unreachable RV', () async {
+      // Bind+close to get a definitely-free port, then connect — refused fast.
+      final temp = await ServerSocket.bind('127.0.0.1', 0);
+      final closedPort = temp.port;
+      await temp.close();
+
+      await sshnpd.clientRequestNotificationHandler(
+        latencyRequest(
+          id: 'aaaa1111-0000-0000-0000-000000000002',
+          value: jsonEncode({
+            '@rv1': {'ipaddr': '127.0.0.1', 'port': closedPort},
+          }),
+        ),
+      );
+
+      expect(sentNotifications, hasLength(1));
+      final response = decodeLatencyResponse(sentNotifications.single);
+      expect(response['@rv1'], -1);
+    });
+
+    test('sends no response when value is null', () async {
+      await sshnpd.clientRequestNotificationHandler(
+        latencyRequest(id: 'aaaa1111-0000-0000-0000-000000000003', value: null),
+      );
+
+      expect(sentNotifications, isEmpty);
+    });
+
+    test('sends no response when value is malformed JSON', () async {
+      await sshnpd.clientRequestNotificationHandler(
+        latencyRequest(
+          id: 'aaaa1111-0000-0000-0000-000000000004',
+          value: 'not-json',
+        ),
+      );
+
+      expect(sentNotifications, isEmpty);
+    });
+
+    test('responds with empty map when rvServers is empty', () async {
+      await sshnpd.clientRequestNotificationHandler(
+        latencyRequest(id: 'aaaa1111-0000-0000-0000-000000000006', value: '{}'),
+      );
+
+      expect(sentNotifications, hasLength(1));
+      final response = decodeLatencyResponse(sentNotifications.single);
+      expect(response, isEmpty);
+    });
+  });
+}

