+  // ── Confirmed-detection flag in exports ──────────────────────────────
+
+  group('confirmed-detection flag in exports', () {
+    DetectionRecord flaggableDet(DateTime start, {bool confirmed = false}) {
+      return DetectionRecord(
+        scientificName: 'Turdus merula',
+        commonName: 'Eurasian Blackbird',
+        confidence: 0.91,
+        timestamp: start.add(const Duration(seconds: 5)),
+        latitude: 52.52,
+        longitude: 13.40,
+        confirmedAt: confirmed ? DateTime.now().toUtc() : null,
+      );
+    }
+
+    List<String> keyedRow(String text, Pattern sep) {
+      final lines = text.split('\n');
+      final header = lines.first.split(sep);
+      final row = lines[1].split(sep);
+      expect(header.length, row.length);
+      return List.generate(header.length, (i) => '${header[i]}=${row[i]}');
+    }
+
+    // True when the value renders the detection as positively confirmed,
+    // as opposed to merely carrying empty/inert confirmation data. Timestamps
+    // alone are never considered a positive confirmation marker: an
+    // implementation may always emit a 'last reviewed at'-style column.
+    bool rendersPositivelyConfirmed(Object? value) {
+      if (value == null || value == false) return false;
+      if (value is num) {
+        // Whole-number 0/1 are a common boolean encoding.
+        return value == 1 && value == value.toInt();
+      }
+      if (value is String) {
+        final v = value.trim();
+        if (v.isEmpty) return false;
+        const inert = {
+          'false',
+          'no',
+          'n',
+          '0',
+          'null',
+          'none',
+          'unconfirmed',
+          '-',
+        };
+        if (inert.contains(v.toLowerCase())) return false;
+        if (DateTime.tryParse(v) != null) return false;
+        final lower = v.toLowerCase();
+        final positiveWords = RegExp(
+          r'^(true|yes|y|ok|x|check(ed)?|verified?|confirmed?|positives?|marked|done|[✓✔✅☑])$',
+        );
+        return positiveWords.hasMatch(lower);
+      }
+      return true;
+    }
+
+    test('Raven table distinguishes a confirmed detection from an unconfirmed one', () {
+      final start = DateTime.utc(2025, 6, 15, 8, 0, 0);
+      final confirmed = keyedRow(
+        buildRavenSelectionTable(
+          _makeSession(detections: [flaggableDet(start, confirmed: true)]),
+        ),
+        '\t',
+      );
+      final unconfirmed = keyedRow(
+        buildRavenSelectionTable(
+          _makeSession(detections: [flaggableDet(start)]),
+        ),
+        '\t',
+      );
+
+      // The two sessions differ only in the confirmation state, so the
+      // rendered rows must differ somewhere.
+      expect(
+        confirmed.where((cell) => !unconfirmed.contains(cell)),
+        isNotEmpty,
+        reason: 'Raven row must change when the detection is confirmed',
+      );
+    });
+
+    test('CSV distinguishes a confirmed detection from an unconfirmed one', () {
+      final start = DateTime.utc(2025, 6, 15, 8, 0, 0);
+      final confirmed = keyedRow(
+        buildCsvExport(
+          _makeSession(detections: [flaggableDet(start, confirmed: true)]),
+        ),
+        ',',
+      );
+      final unconfirmed = keyedRow(
+        buildCsvExport(
+          _makeSession(detections: [flaggableDet(start)]),
+        ),
+        ',',
+      );
+
+      expect(
+        confirmed.where((cell) => !unconfirmed.contains(cell)),
+        isNotEmpty,
+        reason: 'CSV row must change when the detection is confirmed',
+      );
+    });
+
+    test('JSON export reflects the per-detection confirmation state', () {
+      final start = DateTime.utc(2025, 6, 15, 8, 0, 0);
+      Map<String, dynamic> jsonOf(bool confirmed) {
+        final session = _makeSession(
+          detections: [flaggableDet(start, confirmed: confirmed)],
+        );
+        final map = jsonDecode(buildJsonExport(session)) as Map<String, dynamic>;
+        return (map['detections'] as List).single as Map<String, dynamic>;
+      }
+
+      // The two sessions differ only in the confirmation state, so the
+      // exported detection entries must differ somewhere, whatever the
+      // chosen representation.
+      expect(jsonOf(true), isNot(equals(jsonOf(false))));
+    });
+
+    test('GPX marks confirmed waypoints and leaves others unmarked', () {
+      final start = DateTime.utc(2025, 6, 15, 8, 0, 0);
+      final session = _makeSession(
+        type: SessionType.survey,
+        detections: [
+          DetectionRecord(
+            scientificName: 'Turdus merula',
+            commonName: 'Eurasian Blackbird',
+            confidence: 0.91,
+            timestamp: start.add(const Duration(seconds: 5)),
+            latitude: 52.52,
+            longitude: 13.40,
+            confirmedAt: DateTime.now().toUtc(),
+          ),
+          DetectionRecord(
+            scientificName: 'Erithacus rubecula',
+            commonName: 'European Robin',
+            confidence: 0.80,
+            timestamp: start.add(const Duration(seconds: 10)),
+            latitude: 52.53,
+            longitude: 13.41,
+          ),
+        ],
+      );
+
+      final gpx = buildGpxExport(session);
+      final wptStart = gpx.indexOf('<wpt ');
+      final firstEnd = gpx.indexOf('</wpt>', wptStart);
+      final secondStart = gpx.indexOf('<wpt ', firstEnd);
+      final secondEnd = gpx.indexOf('</wpt>', secondStart);
+      final firstWpt = gpx.substring(wptStart, firstEnd);
+      final secondWpt = gpx.substring(secondStart, secondEnd);
+      expect(firstWpt, contains('Eurasian Blackbird'));
+      expect(secondWpt, contains('European Robin'));
+
+      // Neighbouring waypoints that differ only in confirmation state.
+      final confirmedOnly = _makeSession(
+        type: SessionType.survey,
+        detections: [
+          flaggableDet(start, confirmed: true),
+          flaggableDet(start),
+        ],
+      );
+      final confirmedGpx = buildGpxExport(confirmedOnly);
+      final cStart = confirmedGpx.indexOf('<wpt ');
+      final cEnd = confirmedGpx.indexOf('</wpt>', cStart);
+      final uStart = confirmedGpx.indexOf('<wpt ', cEnd);
+      final uEnd = confirmedGpx.indexOf('</wpt>', uStart);
+      final confirmedWpt = confirmedGpx.substring(cStart, cEnd);
+      final unconfirmedWpt = confirmedGpx.substring(uStart, uEnd);
+
+      // The confirmed waypoint must be distinguishable from an otherwise
+      // identical unconfirmed one, whatever marker is chosen.
+      expect(
+        confirmedWpt,
+        isNot(equals(unconfirmedWpt)),
+        reason: 'GPX waypoint must change when the detection is confirmed',
+      );
+    });
+
+    test('unconfirmed detections are not represented as positively confirmed in any export', () {
+      final start = DateTime.utc(2025, 6, 15, 8, 0, 0);
+      final session = _makeSession(detections: [flaggableDet(start)]);
+
+      // JSON: no entry may actively assert a positive confirmation (keys are
+      // untouched, so this stays representation-neutral).
+      final json = jsonDecode(buildJsonExport(session)) as Map<String, dynamic>;
+      final detEntry =
+          (json['detections'] as List).single as Map<String, dynamic>;
+      expect(
+        detEntry.values.every((v) => !rendersPositivelyConfirmed(v)),
+        isTrue,
+        reason: 'unconfirmed detection must not look confirmed in JSON',
+      );
+
+      // A column whose value in this row reads as a negative or inert
+      // confirmation marker is acceptable; a positive one is not.
+      List<String> positiveCells(String text, Pattern sep) {
+        final lines = text.split('\n');
+        final header = lines.first.split(sep);
+        final row = lines[1].split(sep);
+        // Values that merely echo a header cell verbatim (e.g. the species
+        // name columns, or a survey time duplicating begin time) cannot be a
+        // confirmation marker.
+        final shared = <String>{}
+          ..addAll(header.where((h) => row.contains(h)));
+        return [
+          for (var i = 0; i < row.length; i++)
+            if (rendersPositivelyConfirmed(row[i]) &&
+                !header[i].contains(row[i]) &&
+                !shared.contains(row[i]))
+              '${header[i]}=${row[i]}',
+        ];
+      }
+
+      expect(
+        positiveCells(buildRavenSelectionTable(session), '\t'),
+        isEmpty,
+        reason: 'unconfirmed detection must not look confirmed in Raven',
+      );
+      expect(
+        positiveCells(buildCsvExport(session), ','),
+        isEmpty,
+        reason: 'unconfirmed detection must not look confirmed in CSV',
+      );
+    });
+  });
 }
