+import 'dart:io';
+
+import 'package:analyzer/dart/analysis/analysis_context_collection.dart';
+import 'package:analyzer/dart/analysis/results.dart';
+// ignore: depend_on_referenced_packages
+import 'package:analyzer/file_system/file_system.dart' as analyzer_fs;
+// ignore: depend_on_referenced_packages
+import 'package:analyzer/file_system/overlay_file_system.dart';
+// ignore: depend_on_referenced_packages
+import 'package:analyzer/file_system/physical_file_system.dart';
+import 'package:test/test.dart';
+
+void main() {
+  group('Given the skills package library after the agent rename', () {
+    late Directory packageRoot;
+    late File skillsLibraryFile;
+
+    // Reads `package:skills/skills.dart` so its export directives can be
+    // combined with legacy import URIs into synthetic probe sources.
+    setUp(() {
+      packageRoot = Directory.current;
+      skillsLibraryFile = File(
+        '${packageRoot.path}${Platform.pathSeparator}lib'
+        '${Platform.pathSeparator}skills.dart',
+      );
+      expect(
+        skillsLibraryFile.existsSync(),
+        isTrue,
+        reason:
+            'expected to locate the package public library at '
+            '${skillsLibraryFile.path}',
+      );
+    });
+
+    tearDown(() async {
+      // No filesystem artifacts are created: analysis runs entirely against
+      // in-memory overlay sources.
+    });
+
+    Future<List<_ProbeDiagnostic>> probeErrors(List<String> importLines) async {
+      final exports = skillsLibraryFile
+          .readAsStringSync()
+          .split('\n')
+          .map((line) => line.trim())
+          .where((line) => line.startsWith('export '))
+          .toList();
+      final source = [
+        ...importLines,
+        ...exports,
+        'void probe() {}',
+        '',
+      ].join('\n');
+
+      final targetPath =
+          '${packageRoot.path}'
+          '${Platform.pathSeparator}agent_api_surface_probe.dart';
+      final collection = AnalysisContextCollection(
+        includedPaths: [packageRoot.path],
+        resourceProvider: _overlayProvider(source, targetPath),
+      );
+      final session = collection.contextFor(targetPath).currentSession;
+      final result = await session.getErrors(targetPath) as ErrorsResult;
+      final probeLines = importLines.length;
+      final diagnostics = <_ProbeDiagnostic>[];
+      for (final error in result.errors) {
+        final location = result.lineInfo.getLocation(error.offset);
+        // Only diagnostics anchored on the synthetic import/export lines at
+        // the top of the probe are relevant; anything else (for example a
+        // `package:skills/skills.dart` that still re-exports removed legacy
+        // libraries) is reported separately by the caller.
+        if (location.lineNumber <= probeLines) {
+          diagnostics.add(
+            _ProbeDiagnostic(
+              name: error.diagnosticCode.name,
+              line: location.lineNumber,
+            ),
+          );
+        }
+      }
+      return diagnostics;
+    }
+
+    group('when importing the former IDE-named libraries '
+        'alongside the public exports', () {
+      test('then every legacy import is an unresolvable URI', () async {
+        final diagnostics = await probeErrors([
+          "import 'package:skills/src/ide/ide.dart';",
+          "import 'package:skills/src/ide/ide_adapter.dart';",
+          "import 'package:skills/src/ide/ide_adapter_factory.dart';",
+          "import 'package:skills/src/ide/adapters/agent_skills_adapter.dart';",
+          "import 'package:skills/src/ide/adapters/claude_adapter.dart';",
+          "import 'package:skills/src/ide/adapters/cline_adapter.dart';",
+          "import 'package:skills/src/ide/adapters/copilot_adapter.dart';",
+          "import 'package:skills/src/ide/adapters/cursor_adapter.dart';",
+          "import 'package:skills/src/ide/adapters/generic_adapter.dart';",
+          "import 'package:skills/src/ide/adapters/opencode_adapter.dart';",
+        ]);
+
+        expect(
+          diagnostics.toSet(),
+          {
+            for (var line = 1; line <= 10; line++)
+              _ProbeDiagnostic(name: 'uri_does_not_exist', line: line),
+          },
+          reason:
+              'expected each former IDE-named library import to fail '
+              'with an unresolvable URI, got: $diagnostics',
+        );
+      });
+    });
+
+    group('when exporting legacy IDE-named module re-export files '
+        'together with the public library', () {
+      test('then every legacy export is an unresolvable URI', () async {
+        final diagnostics = await probeErrors([
+          "export 'src/ide/ide.dart';",
+          "export 'src/ide/ide_adapter.dart';",
+          "export 'src/ide/ide_adapter_factory.dart';",
+          "export 'src/ide/adapters/claude_adapter.dart';",
+        ]);
+
+        expect(
+          diagnostics.toSet(),
+          {
+            for (var line = 1; line <= 4; line++)
+              _ProbeDiagnostic(name: 'uri_does_not_exist', line: line),
+          },
+          reason:
+              'expected each former IDE-named export to fail with an '
+              'unresolvable URI, got: $diagnostics',
+        );
+      });
+    });
+  });
+}
+
+analyzer_fs.ResourceProvider _overlayProvider(
+  String content,
+  String targetPath,
+) {
+  final overlay = OverlayResourceProvider(PhysicalResourceProvider.INSTANCE)
+    ..setOverlay(targetPath, content: content, modificationStamp: 0);
+  return overlay;
+}
+
+/// A diagnostic anchored on a specific probe source line.
+class _ProbeDiagnostic {
+  const _ProbeDiagnostic({required this.name, required this.line});
+
+  final String name;
+  final int line;
+
+  @override
+  bool operator ==(Object other) =>
+      other is _ProbeDiagnostic && other.name == name && other.line == line;
+
+  @override
+  int get hashCode => Object.hash(name, line);
+
+  @override
+  String toString() => '$name at probe line $line';
+}

