+/// Checks of the separation contract for the recorded-uses collections:
+/// recordings of static calls and recordings of const instances live in
+/// their own collections under `uses`, `uses` permits exactly those two
+/// collections, and a document with no recordings at all is valid.
+void recordedUsesSeparationTests(
+  JsonSchema schema,
+  String recordedUsesData,
+) {
+  Map<String, Object?> copyOfRecordedUses() =>
+      jsonDecode(recordedUsesData) as Map<String, Object?>;
+
+  void expectValid(Map<String, Object?> document) {
+    final result = schema.validate(document);
+    printOnFailure(result.toString());
+    expect(result.isValid, isTrue, reason: result.toString());
+  }
+
+  void expectInvalid(Map<String, Object?> document) {
+    final result = schema.validate(document);
+    printOnFailure(result.toString());
+    expect(result.isValid, isFalse, reason: result.toString());
+  }
+
+  test('A document without any recorded uses is valid', () {
+    final document = <String, Object?>{
+      'metadata': {'comment': 'no recorded uses', 'version': '0.0.0'},
+    };
+    expectValid(document);
+    expect(document, isNot(contains('uses')));
+  });
+
+  test('A document with an unknown property in uses is invalid', () {
+    final document = copyOfRecordedUses();
+    (document['uses']! as Map<String, Object?>)['recordings'] = <void>[];
+    expectInvalid(document);
+  });
+
+  test('A document recording only static calls is valid', () {
+    final document = copyOfRecordedUses();
+    (document['uses']! as Map<String, Object?>).remove('instances');
+    expectValid(document);
+  });
+
+  test('A document recording only const instances is valid', () {
+    final document = copyOfRecordedUses();
+    (document['uses']! as Map<String, Object?>).remove('static_calls');
+    expectValid(document);
+  });
+
+  test('A recording entry with an empty list of uses is invalid', () {
+    for (final collection in ['static_calls', 'instances']) {
+      final document = copyOfRecordedUses();
+      final recordings =
+          (document['uses']! as Map<String, Object?>)[collection]!
+              as List<Object?>;
+      final recording = recordings.first! as Map<String, Object?>;
+      recordings[0] = {...recording, 'uses': <void>[]};
+      expectInvalid(document);
+    }
+  });
+
+  test('A recording entry carrying a field of the other kind is invalid', () {
+    final documentCalls = copyOfRecordedUses();
+    final staticCallRecordings =
+        (documentCalls['uses']! as Map<String, Object?>)['static_calls']!
+            as List<Object?>;
+    final staticCallRecording = staticCallRecordings.first!
+        as Map<String, Object?>;
+    staticCallRecordings[0] = {...staticCallRecording, 'instances': <void>[]};
+    final staticCallResult = schema.validate(documentCalls);
+    printOnFailure(staticCallResult.toString());
+    expect(staticCallResult.isValid, isFalse);
+    expect(
+      staticCallResult.toString(),
+      contains('unallowed additional property instances'),
+      reason: staticCallResult.toString(),
+    );
+
+    final documentInstances = copyOfRecordedUses();
+    final instanceRecordings =
+        (documentInstances['uses']! as Map<String, Object?>)['instances']!
+            as List<Object?>;
+    final instanceRecording = instanceRecordings.first!
+        as Map<String, Object?>;
+    instanceRecordings[0] = {...instanceRecording, 'static_calls': <void>[]};
+    final instanceResult = schema.validate(documentInstances);
+    printOnFailure(instanceResult.toString());
+    expect(instanceResult.isValid, isFalse);
+    expect(
+      instanceResult.toString(),
+      contains('unallowed additional property static_calls'),
+      reason: instanceResult.toString(),
+    );
+  });
+
+  test('A recording entry permits only definition_index and uses', () {
+    for (final collection in ['static_calls', 'instances']) {
+      final document = copyOfRecordedUses();
+      final recordings =
+          (document['uses']! as Map<String, Object?>)[collection]!
+              as List<Object?>;
+      final recording = recordings.first! as Map<String, Object?>;
+      recordings[0] = {...recording, 'unknown_property': true};
+      final result = schema.validate(document);
+      printOnFailure(result.toString());
+      expect(result.isValid, isFalse);
+      expect(
+        result.toString(),
+        contains('unallowed additional property unknown_property'),
+        reason: result.toString(),
+      );
+    }
+  });
+}
+
+void recordedUsesParsingTests() {
+  test('Parsing a document with an empty uses object yields no recordings',
+      () {
+    final document = Recordings.fromJson(<String, Object?>{
+      'metadata': {'version': version.toString(), 'comment': 'empty uses'},
+      'uses': const <String, Object?>{},
+    });
+    expect(document.calls, isEmpty);
+    expect(document.instances, isEmpty);
+  });
+
+  test('Parsing a document without uses yields no recordings', () {
+    final document = Recordings.fromJson(<String, Object?>{
+      'metadata': {'version': version.toString(), 'comment': 'no uses'},
+    });
+    expect(document.calls, isEmpty);
+    expect(document.instances, isEmpty);
+  });
+}
