diff --git a/packages/google_cloud_firestore/test/bulk_writer_test.dart b/packages/google_cloud_firestore/test/bulk_writer_test.dart
new file mode 100644
index 0000000..a166590
--- /dev/null
+++ b/packages/google_cloud_firestore/test/bulk_writer_test.dart
@@ -0,0 +1,143 @@
+import 'dart:io';
+
+import 'package:test/test.dart';
+
+import 'rename_contract_helpers.dart';
+
+/// Probe program exercising `Settings`, `Firestore`, and `BulkWriter`
+/// behaviors that must keep working while the standalone Firestore client
+/// library retains its current (pre-rename) package identity.
+const String _preRenameBehaviorProbe =
+    '''
+import 'dart:async';
+
+import 'package:$packageNameToken/$packageNameToken.dart';
+
+void main() {
+  final settings = Settings(projectId: 'contract-project');
+  if (settings.projectId != 'contract-project') {
+    throw StateError('Settings.projectId changed');
+  }
+  late Firestore firestore;
+  runZoned(
+    () {
+      firestore = Firestore(settings: settings);
+    },
+    zoneValues: {
+      envSymbol: <String, String>{'GOOGLE_CLOUD_PROJECT': 'contract-project'},
+    },
+  );
+  if (firestore.projectId != 'contract-project') {
+    throw StateError('Firestore.projectId changed');
+  }
+  final doc = firestore.doc('collection/document');
+  if (doc.path != 'collection/document') {
+    throw StateError('Firestore.doc() changed');
+  }
+  final writer = firestore.bulkWriter();
+  writer.onWriteError((error) => true);
+  writer.onWriteResult((reference, result) {});
+  if (writer.bufferedOperationsCount != 0) {
+    throw StateError('BulkWriter.bufferedOperationsCount changed');
+  }
+  if (writer.pendingOperationsCount != 0) {
+    throw StateError('BulkWriter.pendingOperationsCount changed');
+  }
+}
+''';
+
+void main() {
+  late final Directory root;
+
+  setUpAll(() {
+    root = findRepositoryRoot();
+  });
+
+  test('generated version file declares packageVersion', () {
+    // `gen-version.sh`, which runs before these suites, derives
+    // `lib/version.g.dart` from the package pubspec, so the file must
+    // declare `packageVersion` in every repository state (pre-rename and
+    // post-rename alike).
+    final candidates = <String>[
+      'packages/$legacyPackageName',
+      'packages/$renamedPackageName',
+    ].where((path) => repoPathExists(root, '$path/pubspec.yaml')).toList();
+    expect(
+      candidates,
+      hasLength(1),
+      reason:
+          'exactly one package directory must declare a pubspec for the '
+          'standalone Firestore client library (packages/$legacyPackageName '
+          'before the rename, packages/$renamedPackageName after it)',
+    );
+    final content = readRequiredRepoFile(
+      root,
+      '${candidates.single}/lib/version.g.dart',
+    );
+    expect(
+      content,
+      contains(RegExp('const String packageVersion = ')),
+      reason:
+          'the repository `gen-version.sh` (run before these tests) must '
+          'generate ${candidates.single}/lib/version.g.dart declaring '
+          '`packageVersion` for the current package',
+    );
+  });
+
+  test(
+    'BulkWriter behavior is preserved under the current entry point',
+    () async {
+      // This invariant only holds while the library still exposes its
+      // legacy identity; once the rename completes the workspace resolves
+      // only the renamed package and there is nothing left to check.
+      final workspaceConfig = readWorkspaceConfig(root);
+      if (!workspaceResolves(workspaceConfig, legacyPackageName)) {
+        return;
+      }
+      final result = await compileAndRunDartProbe(
+        root,
+        'rename_contract_bulk_writer_current',
+        _preRenameBehaviorProbe.replaceAll(packageNameToken, legacyPackageName),
+      );
+      expect(
+        result.exitCode,
+        0,
+        reason:
+            'driving the documented BulkWriter behaviors through '
+            '`$legacyEntryPoint` must succeed while the standalone '
+            'Firestore client library is not renamed.\n'
+            'exit code: ${result.exitCode}\n'
+            'stdout:\n${result.stdout}\n'
+            'stderr:\n${result.stderr}',
+      );
+    },
+    timeout: const Timeout(Duration(minutes: 5)),
+  );
+
+  test(
+    'BulkWriter behavior compiles against the renamed entry point',
+    () async {
+      final result = await compileAndRunDartProbe(
+        root,
+        'rename_contract_bulk_writer_renamed',
+        _preRenameBehaviorProbe.replaceAll(
+          packageNameToken,
+          renamedPackageName,
+        ),
+      );
+      expect(
+        result.exitCode,
+        0,
+        reason:
+            'driving the preserved BulkWriter behaviors through '
+            '`$renamedEntryPoint` must compile and succeed after the rename '
+            '(before it `$renamedEntryPoint` does not resolve and this '
+            'check fails compilation).\n'
+            'exit code: ${result.exitCode}\n'
+            'stdout:\n${result.stdout}\n'
+            'stderr:\n${result.stderr}',
+      );
+    },
+    timeout: const Timeout(Duration(minutes: 5)),
+  );
+}
