+import 'dart:io';
+
+import 'package:test/test.dart';
+
+import 'rename_contract_helpers.dart';
+
+/// Probe program constructing a `WriteBatch` through the package's public
+/// entry point and exercising the documented, connectivity-free behavior
+/// of its operations: `create`, `set`, `update`, and `delete` queue writes
+/// and validate their document data eagerly, while misuse is reported with
+/// the documented errors.
+const String _writeBatchBehaviorProbe =
+    '''
+import 'dart:async';
+
+import 'package:$packageNameToken/$packageNameToken.dart';
+
+/// Runs [body] and returns the thrown object, or throws when [body]
+/// returns normally.
+Object caught(void Function() body) {
+  try {
+    body();
+  } on Object catch (error) {
+    return error;
+  }
+  throw StateError('expected the operation to throw, but it returned');
+}
+
+void main() {
+  late Firestore firestore;
+  runZoned(
+    () {
+      firestore = Firestore(
+        settings: Settings(projectId: 'contract-project'),
+      );
+    },
+    zoneValues: {
+      envSymbol: <String, String>{'GOOGLE_CLOUD_PROJECT': 'contract-project'},
+    },
+  );
+
+  final batch = firestore.batch();
+  if (batch is! WriteBatch) {
+    throw StateError('Firestore.batch() changed');
+  }
+
+  // Queueing the documented write operations must not throw for valid
+  // input: nested document data, sentinel and transform values, and merge
+  // options are all accepted without a connection.
+  final docRef = firestore.doc('probe/doc');
+  batch.create(docRef, <String, Object?>{'created': true});
+  batch.set(docRef, <String, Object?>{
+    'title': 'probe',
+    'count': 1,
+    'tags': <String>['a', 'b'],
+    'nested': <String, Object?>{'flag': false},
+  });
+  batch.set(
+    docRef,
+    <String, Object?>{'mergedAt': FieldValue.serverTimestamp},
+    options: SetOptions.merge(),
+  );
+  batch.set(
+    docRef,
+    <String, Object?>{'title': 'probe-2', 'extra': FieldValue.delete},
+    options: SetOptions.mergeFields(<FieldPath>[
+      FieldPath(const <String>['title']),
+    ]),
+  );
+  batch.update(docRef, <FieldPath, Object?>{
+    FieldPath(const <String>['count']): 2,
+  });
+  batch.update(docRef, <FieldPath, Object?>{
+    FieldPath(const <String>['count']): FieldValue.increment(1),
+  });
+  batch.delete(firestore.doc('probe/other'));
+
+  // Queueing invalid document data rejects eagerly with ArgumentError,
+  // as documented for the write operations.
+  final badCreate = caught(() => batch.create(docRef, 42));
+  if (badCreate is! ArgumentError) {
+    throw StateError('WriteBatch.create() validation changed');
+  }
+  final badUpdate = caught(
+    () => batch.update(docRef, const <FieldPath, Object?>{}),
+  );
+  if (badUpdate is! ArgumentError) {
+    throw StateError('WriteBatch.update() validation changed');
+  }
+  final badSet = caught(
+    () => batch.set(docRef, <String, Object?>{'bad': FieldValue.delete}),
+  );
+  if (badSet is! ArgumentError) {
+    throw StateError('WriteBatch.set() sentinel validation changed');
+  }
+
+  // `reset()` clears the queued operations and re-enables the batch.
+  batch.reset();
+  batch.set(docRef, <String, Object?>{'afterReset': true});
+}
+''';
+
+void main() {
+  late final Directory root;
+
+  setUpAll(() {
+    root = findRepositoryRoot();
+  });
+
+  test('automation no longer references the legacy package', () {
+    for (final automationFile in const [
+      '.github/workflows/build.yml',
+      'scripts/firestore-coverage.sh',
+    ]) {
+      if (!repoPathExists(root, automationFile)) {
+        continue;
+      }
+      expect(
+        readRepoFile(root, automationFile),
+        isNot(contains(legacyPackageName)),
+        reason:
+            '$automationFile must no longer reference the retired '
+            '`$legacyPackageName` package name once the rename is complete',
+      );
+    }
+  });
+
+  test(
+    'the dependent package compiles against the renamed package',
+    () async {
+      final probeSource = StringBuffer()
+        ..writeln(
+          "import 'package:$renamedPackageName/$renamedPackageName.dart';",
+        )
+        ..writeln(
+          "import 'package:dart_firebase_admin/dart_firebase_admin.dart';",
+        )
+        ..writeln()
+        ..writeln('void main() {')
+        ..writeln('  final firestoreType = Firestore;')
+        ..writeln('  final appType = FirebaseApp;')
+        ..writeln('  if (firestoreType.toString().isEmpty) {')
+        ..writeln("    throw StateError('Firestore type changed');")
+        ..writeln('  }')
+        ..writeln('  if (appType.toString().isEmpty) {')
+        ..writeln("    throw StateError('FirebaseApp type changed');")
+        ..writeln('  }')
+        ..writeln('}');
+      final result = await compileAndRunDartProbe(
+        root,
+        'rename_contract_dependent_package_renamed',
+        probeSource.toString(),
+      );
+      expect(
+        result.exitCode,
+        0,
+        reason:
+            'the dependent package dart_firebase_admin must compile and '
+            'run against the renamed standalone Firestore client library '
+            '`$renamedEntryPoint` once the rename is complete (before it '
+            '`$renamedEntryPoint` does not resolve and this check fails '
+            'compilation).\n'
+            'exit code: ${result.exitCode}\n'
+            'stdout:\n${result.stdout}\n'
+            'stderr:\n${result.stderr}',
+      );
+    },
+    timeout: const Timeout(Duration(minutes: 5)),
+  );
+
+  test(
+    'WriteBatch behavior is exercised through the current entry point',
+    () async {
+      // The public entry point resolves under exactly one package name at
+      // a time: the legacy name before the rename, the renamed name after
+      // it; this probe therefore holds in every repository state.
+      final packageName = <String>[
+        legacyPackageName,
+        renamedPackageName,
+      ].firstWhere(
+        (name) => repoPathExists(root, 'packages/$name/pubspec.yaml'),
+        orElse: () => fail(
+          'the standalone Firestore client library must be present under '
+          'one of packages/$legacyPackageName or '
+          'packages/$renamedPackageName',
+        ),
+      );
