+        reason:
+            'driving the documented WriteBatch behaviors (create, set, '
+            'update, delete, reset, and the eager input validation of '
+            'those operations) through the current public entry point '
+            '`package:$packageName/$packageName.dart` must compile and '
+            'succeed in every repository state.\n'
+            'exit code: ${result.exitCode}\n'
+            'stdout:\n${result.stdout}\n'
+            'stderr:\n${result.stderr}',
+      );
+    },
+    timeout: const Timeout(Duration(minutes: 5)),
+  );
+
+  test('the current Firestore package keeps its documented structure', () {
+    // This invariant holds before the rename, while it is underway, and
+    // after it is complete: exactly one package identity (`pubspec.yaml`
+    // plus library sources) may host the standalone Firestore client
+    // library at any time.
+    final candidates = <String>[
+      'packages/$legacyPackageName',
+      'packages/$renamedPackageName',
+    ].where((path) => repoPathExists(root, '$path/pubspec.yaml')).toList();
+    expect(
+      candidates,
+      hasLength(1),
+      reason:
+          'exactly one package directory must declare a pubspec for the '
+          'standalone Firestore client library (packages/$legacyPackageName '
+          'before the rename, packages/$renamedPackageName after it); '
+          'found: ${candidates.isEmpty ? 'none' : candidates.join(', ')}',
+    );
+    final packageDir = candidates.single;
+    for (final structure in const ['lib/src/write_batch.dart']) {
+      expect(
+        repoPathExists(root, '$packageDir/$structure'),
+        isTrue,
+        reason:
+            'the standalone Firestore client library at $packageDir must '
+            'keep providing $structure',
+      );
+    }
+    final writer = readRepoFile(root, '$packageDir/lib/src/write_batch.dart');
+    expect(
+      writer,
+      contains('class WriteBatch'),
+      reason:
+          'the standalone Firestore client library at $packageDir must '
+          'keep its WriteBatch implementation',
+    );
+  });
+}
