+/// Shared helpers for the hidden rename-contract suites of the standalone
+/// Firestore client library.
+///
+/// This library intentionally depends only on the Dart SDK, `package:test`,
+/// and no other third-party package. It never imports the package under
+/// test, so every suite that uses it loads and runs identically whether
+/// the standalone Firestore client library is currently named
+/// `googleapis_firestore` (before the rename) or `google_cloud_firestore`
+/// (after the rename).
+library;
+
+import 'dart:convert';
+import 'dart:io';
+
+import 'package:test/test.dart';
+
+/// The name the standalone Firestore package has before the rename.
+const String legacyPackageName = 'googleapis_firestore';
+
+/// The name the standalone Firestore package must have after the rename.
+const String renamedPackageName = 'google_cloud_firestore';
+
+/// The public entry point of the renamed package.
+const String renamedEntryPoint =
+    'package:$renamedPackageName/$renamedPackageName.dart';
+
+/// The public entry point of the legacy package.
+const String legacyEntryPoint =
+    'package:$legacyPackageName/$legacyPackageName.dart';
+
+/// Probe programs substitute this token with [renamedPackageName] (when
+/// probing post-rename requirements) or with [legacyPackageName] (when
+/// probing requirements that hold in every repository state).
+const String packageNameToken = '__PKG_NAME__';
+
+/// Locates the root of the repository checkout (the directory containing
+/// `packages/dart_firebase_admin`), regardless of the working directory the
+/// suites were invoked from (`dart test` may run from the repository root
+/// or from a package directory).
+Directory findRepositoryRoot() {
+  var directory = Directory.current.absolute;
+  for (var i = 0; i < 16; i++) {
+    if (Directory(
+      '${directory.path}/packages/dart_firebase_admin',
+    ).existsSync()) {
+      return directory;
+    }
+    final parent = directory.parent;
+    if (parent.path == directory.path) {
+      break;
+    }
+    directory = parent;
+  }
+  throw StateError(
+    'Could not locate the repository root (a directory containing '
+    'packages/dart_firebase_admin) from ${Directory.current.path}',
+  );
+}
+
+/// Resolves a repository-root-relative path to an absolute file path.
+String repoPath(Directory root, String relativePath) =>
+    '${root.path}/$relativePath';
+
+/// Whether a repository-root-relative path exists on disk.
+bool repoPathExists(Directory root, String relativePath) =>
+    FileSystemEntity.typeSync(repoPath(root, relativePath)) !=
+    FileSystemEntityType.notFound;
+
+/// Reads a repository-root-relative text file.
+String readRepoFile(Directory root, String relativePath) =>
+    File(repoPath(root, relativePath)).readAsStringSync();
+
+/// Returns the content of a file that must exist.
+String readRequiredRepoFile(Directory root, String relativePath) {
+  expect(
+    repoPathExists(root, relativePath),
+    isTrue,
+    reason: '$relativePath must exist',
+  );
+  return readRepoFile(root, relativePath);
+}
+
+/// Parses a repository-owned `pubspec.yaml`; returns null when absent.
+///
+/// Pubspec files in this repository are plain YAML; the assertions only
+/// extract `name` and the top-level dependency sections with a minimal,
+/// dependency-free scan so the helper stays loadable in every state.
+Map<String, Object?>? readPubspec(Directory root, String relativePath) {
+  if (!repoPathExists(root, relativePath)) {
+    return null;
+  }
+  final content = readRepoFile(root, relativePath);
+  final result = <String, Object?>{};
+  final nameMatch = RegExp(
+    r'^name:\s*(\S+)\s*$',
+    multiLine: true,
+  ).firstMatch(content);
+  if (nameMatch != null) {
+    result['name'] = nameMatch.group(1);
+  }
+  final sections = <String, Set<String>>{
+    'dependencies': <String>{},
+    'dev_dependencies': <String>{},
+    'dependency_overrides': <String>{},
+  };
+  String? current;
+  for (final rawLine in content.split('\n')) {
+    if (rawLine.startsWith(RegExp('[a-z_]+:'))) {
+      final section = rawLine.substring(0, rawLine.indexOf(':'));
+      current = sections.containsKey(section) ? section : null;
+      continue;
+    }
+    if (current == null) {
+      continue;
+    }
+    final entry = RegExp(r'^\s\s([a-z0-9_]+):').firstMatch(rawLine);
+    if (entry != null) {
+      sections[current]!.add(entry.group(1)!);
+    }
+  }
+  for (final entry in sections.entries) {
+    result[entry.key] = entry.value.toList()..sort();
+  }
+  return result;
+}
+
+/// Asserts that [pubspec] depends on the standalone Firestore client
+/// library under the name [packageName] and does not declare it under the
+/// other name.
+void expectFirestoreDependency(
+  Map<String, Object?> pubspec,
+  String sourceDescription, {
+  required String packageName,
+  required String excludedName,
+}) {
+  final sections = <Object?>[]
+    ..add(pubspec['dependencies'])
+    ..add(pubspec['dev_dependencies'])
+    ..add(pubspec['dependency_overrides']);
+  final names = <String>{
+    for (final section in sections)
+      if (section is List) ...section.map((name) => name.toString()),
+  };
+  expect(
+    names,
+    contains(packageName),
+    reason:
+        '$sourceDescription must declare a dependency on the standalone '
+        'Firestore client library `$packageName` (it currently declares: '
+        '${names.isEmpty ? 'none' : names.join(', ')})',
+  );
+  expect(
+    names,
+    isNot(contains(excludedName)),
+    reason:
+        '$sourceDescription must no longer declare a dependency on the '
+        'retired `$excludedName` package name',
+  );
+}
+
+/// Ensures a loadable scratch package context exists in a directory
+/// unique to the current test executable (below the operating system
+/// temporary directory, outside the repository checkout — the runner
+/// capabilities of these suites forbid using their package directory
+/// directly because `dart test` watches and re-runs on changes there)
+/// with a valid standalone `package_config.json`, and returns the absolute
+/// path to that configuration file.
+///
+/// Probe programs are written into sibling `probe_<name>` directories, so
+/// they compile and run in every repository state, including states where
+/// parts of the repository itself cannot be compiled. Resolution works as
+/// follows:
+///
+/// 1. After refreshing the repository workspace with `dart pub get`, the
+///    workspace `package_config.json` is copied and every package-path URI
+///    is rewritten to an absolute `file://` URI, so the copy keeps
+///    resolving the repository's own workspace packages no matter where
+///    the probe programs live.
+/// 2. When the workspace cannot resolve (for example while the manifests
+///    are mid-rename), the probe package instead re-exports captured
+///    hosted versions of `package:test`, the matcher, and their support
+///    packages from the SDK pub cache — enough to compile the probes —
+///    plus an entry for every package directory that currently exists
+///    under `packages/`, so the package under test resolves by both its
+///    legacy and its renamed name whenever it is present.
+Future<String> prepareProbeWorkspace(Directory root) async {
+  final probeArea = Directory(_probeAreaPath(root));
+  if (!probeArea.existsSync()) {
+    await probeArea.create(recursive: true);
+  }
+  await _writeProbePackageConfig(root, probeArea);
+  final config = await File(
+    '${_probeAreaPath(root)}/package_config.json',
+  ).readAsString();
+  await Directory(_probeContextPath(root)).create(recursive: true);
+  await File('${_probeContextPath(root)}/pubspec.yaml').writeAsString(
+    'name: rename_contract_probe\n'
+    'publish_to: none\n'
+    'environment:\n'
+    "  sdk: '>=3.9.0 <4.0.0'\n",
+  );
+  await File(
+    '${_probeContextPath(root)}/package_config.json',
+  ).writeAsString(config);
+  await File(
+    '${_probeContextPath(root)}/package_graph.json',
+  ).writeAsString(_probePackageGraph(config));
+  return '${_probeContextPath(root)}/package_config.json';
+}
+
+/// The absolute path of the scratch context where probe programs live.
+///
+/// The scratch area is dedicated to this test executable (its name and
+/// process ID), so concurrent suites never observe each other's probe
+/// programs even when they run in parallel.
+String _probeAreaPath(Directory root) {
+  final executableName = Platform.resolvedExecutable
+      .split(Platform.pathSeparator)
+      .last
+      .replaceAll(RegExp('[^A-Za-z0-9_.-]'), '_');
+  return '${Directory.systemTemp.path}/firebase_admin_rename_contract_'
+      '${executableName}_${pid}';
+}
+
+String _probeContextPath(Directory root) => '${_probeAreaPath(root)}/probe';
+
+String _probeProgramDirPath(Directory root, String programName) =>
+    '${_probeAreaPath(root)}/probe_$programName';
+
+/// A `Duration` longer than a typical hosted resolution attempt; used to
+/// cap the workspace refresh.
+const Duration _pubGetTimeout = Duration(seconds: 120);
+
+Future<void> _writeProbePackageConfig(Directory root, Directory probeArea) {
+  return _resolveWorkspaceConfig(root).then(
+    (workspaceConfig) => _writeResolvedConfig(root, probeArea, workspaceConfig),
+    onError: (_) => _writeFallbackConfig(root, probeArea),
+  );
+}
+
+/// Runs `dart pub get` in the repository root and returns the refreshed
+/// workspace `package_config.json`, or throws when the workspace cannot
+/// resolve the current manifests.
+Future<Map<String, Object?>> _resolveWorkspaceConfig(Directory root) async {
+  try {
+    final result = await Process.run(Platform.resolvedExecutable, const [
+      'pub',
+      'get',
+    ], workingDirectory: root.path).timeout(_pubGetTimeout);
+    if (result.exitCode != 0) {
+      throw StateError(
+        '`dart pub get` rejected the current manifests (exit code '
+        '${result.exitCode}); the repository is in a mid-rename state:\n'
+        '${result.stderr}',
+      );
+    }
+  } on Object {
+    rethrow;
+  }
+  return readWorkspaceConfig(root);
+}
+
+/// Reads the workspace `package_config.json` that `dart pub get` last
+/// generated for the repository, or throws when none exists.
+Map<String, Object?> readWorkspaceConfig(Directory root) {
+  final configFile = File(repoPath(root, '.dart_tool/package_config.json'));
+  if (!configFile.existsSync()) {
+    throw StateError(
+      'the repository workspace has no package_config.json and '
+      '`dart pub get` could not produce one; the manifests are '
+      'unresolvable in the current (mid-rename) state',
+    );
+  }
+  final parsed = jsonDecode(configFile.readAsStringSync());
+  if (parsed is Map) {
+    return parsed.map((key, value) => MapEntry(key.toString(), value));
+  }
+  throw StateError('unexpected package_config.json content');
+}
+
+/// The `package:test`-compatible packages a probe program may import,
+/// together with their repo-cache versions; used only when the workspace
+/// itself cannot resolve so probes (whose test files never import the
+/// package under test) can still compile and run.
+const Map<String, String> _fallbackHostedPackages = <String, String>{
+  '_fe_analyzer_shared': '96.0.0',
+  'analyzer': '10.2.0',
+  'args': '2.7.0',
+  'async': '2.13.0',
+  'boolean_selector': '2.1.2',
+  'collection': '1.19.1',
+  'convert': '3.1.2',
+  'coverage': '1.15.1',
+  'crypto': '3.0.7',
+  'file': '7.0.4',
+  'frontend_server_client': '4.1.0',
+  'glob': '2.1.3',
+  'http': '1.6.0',
+  'http_multi_server': '3.2.2',
+  'http_parser': '4.1.2',
+  'io': '1.0.5',
+  'js': '0.7.2',
+  'logging': '1.3.0',
+  'matcher': '0.12.20',
+  'meta': '1.19.0',
+  'mime': '2.0.0',
+  'node_preamble': '2.0.2',
+  'package_config': '2.2.0',
+  'path': '1.9.1',
+  'pool': '1.5.2',
+  'pub_semver': '2.2.0',
+  'shelf': '1.4.2',
+  'shelf_packages_handler': '3.0.2',
+  'shelf_static': '1.1.3',
+  'shelf_web_socket': '3.0.0',
+  'source_map_stack_trace': '2.1.2',
+  'source_maps': '0.10.13',
+  'source_span': '1.10.1',
+  'stack_trace': '1.12.1',
+  'stream_channel': '2.1.4',
+  'string_scanner': '1.4.1',
+  'term_glyph': '1.2.2',
+  'test': '1.26.3',
+  'test_api': '0.7.7',
+  'test_core': '0.6.11',
+  'typed_data': '1.4.0',
+  'vm_service': '15.0.2',
+  'watcher': '1.1.4',
+  'web': '1.1.1',
+  'web_socket': '1.0.1',
+  'web_socket_channel': '3.0.3',
+  'webkit_inspection_protocol': '1.2.1',
+  'yaml': '3.1.3',
+};
+
+Future<void> _writeResolvedConfig(
+  Directory root,
+  Directory probeArea,
+  Map<String, Object?> workspaceConfig,
+) async {
+  final packages = <Map<String, Object?>>[];
+  final rawPackages = workspaceConfig['packages'];
+  if (rawPackages is List) {
+    for (final rawEntry in rawPackages) {
+      if (rawEntry is! Map) {
+        continue;
+      }
+      final entry = rawEntry.map((k, v) => MapEntry(k.toString(), v));
+      final rootUri = entry['rootUri']?.toString() ?? '';
+      final packageUri = entry['packageUri']?.toString() ?? 'lib/';
+      packages.add(<String, Object?>{
+        'name': entry['name']?.toString() ?? '',
+        'rootUri': _absoluteRootUri(root, rootUri),
+        'packageUri': packageUri,
+        if (entry.containsKey('languageVersion'))
+          'languageVersion': entry['languageVersion'],
+      });
+    }
+  }
+  await _writeConfig(probeArea, packages);
+}
+
+Future<void> _writeFallbackConfig(Directory root, Directory probeArea) async {
+  final packages = <Map<String, Object?>>[];
+  final pubCache = _hostedPubCacheRoot();
+  _fallbackHostedPackages.forEach((name, version) {
+    final dir = Directory('$pubCache/$name-$version');
+    if (dir.existsSync()) {
+      packages.add(<String, Object?>{
+        'name': name,
+        'rootUri': dir.uri.toString(),
+        'packageUri': 'lib/',
+      });
+    }
+  });
+  final packagesDir = Directory(repoPath(root, 'packages'));
+  if (packagesDir.existsSync()) {
+    for (final entity in packagesDir.listSync()) {
+      if (entity is! Directory) {
+        continue;
+      }
+      final pubspec = File('${entity.path}/pubspec.yaml');
+      if (!pubspec.existsSync()) {
+        continue;
+      }
+      final nameMatch = RegExp(
+        r'^name:\s*(\S+)\s*$',
+        multiLine: true,
+      ).firstMatch(pubspec.readAsStringSync());
+      if (nameMatch == null) {
+        continue;
+      }
+      final name = nameMatch.group(1)!;
+      if (packages.any((p) => p['name'] == name)) {
+        continue;
+      }
+      packages.add(<String, Object?>{
+        'name': name,
+        'rootUri': entity.uri.toString(),
+        'packageUri': 'lib/',
+      });
+    }
+  }
+  await _writeConfig(probeArea, packages);
+}
+
+Future<void> _writeConfig(
+  Directory probeArea,
+  List<Map<String, Object?>> packages,
+) async {
+  await File('${probeArea.path}/package_config.json').writeAsString(
+    jsonEncode(<String, Object?>{
+      'configVersion': 2,
+      'packages': packages,
+      'generated': DateTime.now().toIso8601String(),
+      'generator': 'rename_contract_helpers',
+    }),
+  );
+}
+
+/// Builds a minimal `package_graph.json` marking `rename_contract_probe`
+/// as a leaf root package, so `dart run` accepts the probe context
+/// directory as its package context.
+String _probePackageGraph(String packageConfigJson) {
+  final parsed = jsonDecode(packageConfigJson);
+  final rawPackages = parsed is Map ? parsed['packages'] : null;
+  final names = <String>[
+    if (rawPackages is List)
+      for (final entry in rawPackages)
+        if (entry is Map && entry['name'] != null) entry['name'].toString(),
+  ];
+  return jsonEncode(<String, Object?>{
+    'roots': const [r'$package'],
+    'packages': <Object?>[
+      <String, Object?>{
+        'name': 'rename_contract_probe',
+        'version': '0.0.0',
+        'dependencies': names,
+      },
+      for (final name in names)
+        <String, Object?>{
+          'name': name,
+          'version': '0.0.0',
+          'dependencies': const <String>[],
+        },
+    ],
+    'configVersion': 1,
+  });
+}
+
+/// The root directory of the hosted pub cache, for fallback resolution.
+String _hostedPubCacheRoot() {
+  final fromEnv = Platform.environment['PUB_CACHE'];
+  final cacheRoot = (fromEnv != null && fromEnv.isNotEmpty)
+      ? fromEnv
+      : '${Platform.environment['HOME'] ?? ''}/.pub-cache';
+  return '$cacheRoot/hosted/pub.dev';
+}
+
+/// Rewrites a `rootUri` from a `package_config.json` into an absolute
+/// `file://` URI.
+///
+/// `dart pub get` in a workspace writes relative URIs such as
+/// `../packages/google_cloud_firestore` (relative to the `.dart_tool/`
+/// directory that hosts the configuration). Probe programs run from a
+/// scratch directory outside the repository, so relative URIs would
+/// resolve incorrectly; this converts every URI to an absolute one by
+/// resolving it against the absolute URI of the repository `.dart_tool/`
+/// directory.
+String _absoluteRootUri(Directory root, String rootUri) {
+  final parsed = Uri.parse(rootUri);
+  if (parsed.hasScheme) {
+    return rootUri;
+  }
+  final configDirUri = Directory('${root.path}/.dart_tool').absolute.uri;
+  return configDirUri.resolveUri(parsed).toString();
+}
+
+/// Compiles [programSource] to kernel first, and only when compilation
+/// succeeds runs it as `main.dart` of a probe sub-package. Returns the
+/// completed [ProcessResult] of the compilation (when compilation failed)
+/// or of the program run.
+/// Runs [programSource] as a probe program. The probe sources and their
+/// compiled kernel artifacts are written into a scratch area dedicated to
+/// this test executable, keeping the repository checkout (and in
+/// particular the test package directory the runner watches) untouched.
+Future<ProcessResult> compileAndRunDartProbe(
+  Directory root,
+  String programName,
+  String programSource,
+) async {
+  final packagesConfig = await prepareProbeWorkspace(root);
+  final probeDir = Directory(_probeProgramDirPath(root, programName));
+  if (probeDir.existsSync()) {
+    await probeDir.delete(recursive: true);
+  }
+  await probeDir.create(recursive: true);
+  final programFile = File('${probeDir.path}/main.dart');
+  await programFile.writeAsString(programSource);
+  final compilation = await Process.run(Platform.resolvedExecutable, [
+    'compile',
+    'exe',
+    '--packages=$packagesConfig',
+    '-o',
+    '${probeDir.path}/main.exe',
+    programFile.path,
+  ], workingDirectory: probeDir.path);
+  if (compilation.exitCode == 0) {
+    await File('${probeDir.path}/main.exe').delete();
+  }
+  return compilation;
+}
+
+/// Asserts that the repository devendency graph currently resolves: the
+/// workspace `dart pub get` must succeed against the checked-in
+/// `pubspec.yaml` files. Returns the workspace configuration.
+Future<Map<String, Object?>> expectResolvableWorkspace(Directory root) async {
+  final result = await Process.run(Platform.resolvedExecutable, const [
+    'pub',
+    'get',
+  ], workingDirectory: root.path);
+  if (result.exitCode == 0) {
+    return readWorkspaceConfig(root);
+  }
+  fail(
+    '`dart pub get` must succeed for the repository workspace in the '
+    'current state.\nexit code: ${result.exitCode}\n'
+    'stdout:\n${result.stdout}\nstderr:\n${result.stderr}',
+  );
+}
+
+/// Whether the workspace configuration resolves [packageName] at all.
+bool workspaceResolves(
+  Map<String, Object?> workspaceConfig,
+  String packageName,
+) {
+  final packages = workspaceConfig['packages'];
+  if (packages is! List) {
+    return false;
+  }
+  return packages.any((entry) => entry is Map && entry['name'] == packageName);
+}
