+import 'dart:io';
+
+import 'package:test/test.dart';
+
+import 'rename_contract_helpers.dart';
+
+/// Probe program exercising the `Timestamp` construction and conversion
+/// behaviors that existed before the rename and must keep working
+/// identically afterwards.
+const String _behaviorProbe =
+    '''
+import 'dart:async';
+
+import 'package:$packageNameToken/$packageNameToken.dart';
+
+void main() {
+  final timestamp = Timestamp(seconds: 1000, nanoseconds: 500000000);
+  if (timestamp.seconds != 1000 || timestamp.nanoseconds != 500000000) {
+    throw StateError('Timestamp fields changed');
+  }
+  if (timestamp.toMillis() != 1000500) {
+    throw StateError('Timestamp.toMillis() changed');
+  }
+  final roundTrip = Timestamp.fromMillis(timestamp.toMillis());
+  if (roundTrip.seconds != timestamp.seconds ||
+      roundTrip.nanoseconds != timestamp.nanoseconds) {
+    throw StateError('Timestamp.fromMillis() round-trip changed');
+  }
+  final fromDate = Timestamp.fromDate(
+    DateTime.fromMillisecondsSinceEpoch(1000500, isUtc: true),
+  );
+  if (fromDate.seconds != timestamp.seconds) {
+    throw StateError('Timestamp.fromDate() changed');
+  }
+}
+''';
+
+void main() {
+  late final Directory root;
+
+  setUpAll(() {
+    root = findRepositoryRoot();
+  });
+
+  test('package directory is packages/$renamedPackageName '
+      'with a matching pubspec', () {
+    expect(
+      repoPathExists(root, 'packages/$renamedPackageName'),
+      isTrue,
+      reason:
+          'the standalone Firestore client library must live at '
+          'packages/$renamedPackageName after the rename',
+    );
+    final manifest = readPubspec(
+      root,
+      'packages/$renamedPackageName/pubspec.yaml',
+    );
+    expect(
+      manifest,
+      isNotNull,
+      reason:
+          'packages/$renamedPackageName/pubspec.yaml must exist after '
+          'the rename',
+    );
+    expect(
+      manifest!['name'],
+      renamedPackageName,
+      reason:
+          'packages/$renamedPackageName/pubspec.yaml must declare '
+          '`name: $renamedPackageName`',
+    );
+  });
+
+  test(
+    'Timestamp behavior compiles against the renamed entry point',
+    () async {
+      final result = await compileAndRunDartProbe(
+        root,
+        'rename_contract_timestamp_renamed',
+        _behaviorProbe.replaceAll(packageNameToken, renamedPackageName),
+      );
+      expect(
+        result.exitCode,
+        0,
+        reason:
+            'driving the preserved Timestamp behaviors through '
+            '`$renamedEntryPoint` must compile and succeed after the rename '
+            '(before it `$renamedEntryPoint` does not resolve and this '
+            'check fails compilation).\n'
+            'exit code: ${result.exitCode}\n'
+            'stdout:\n${result.stdout}\n'
+            'stderr:\n${result.stderr}',
+      );
+    },
+    timeout: const Timeout(Duration(minutes: 5)),
+  );
+}
