@@ -0,0 +1,64 @@
+import 'dart:io';
+
+import 'package:test/test.dart';
+
+import 'rename_contract_helpers.dart';
+
+/// Probe program exercising the `VectorValue` behaviors that existed
+/// before the rename and must keep working identically afterwards.
+const String _behaviorProbe =
+    '''
+import 'dart:async';
+
+import 'package:$packageNameToken/$packageNameToken.dart';
+
+void main() {
+  final vector = VectorValue(<double>[1.0, -2.5, 3.75]);
+  final values = vector.toArray();
+  if (values.length != 3 || values[0] != 1.0 || values[2] != 3.75) {
+    throw StateError('VectorValue storage changed');
+  }
+  values[0] = 99.0;
+  if (vector.toArray()[0] != 1.0) {
+    throw StateError('VectorValue immutability changed');
+  }
+  if (!vector.isEqual(VectorValue(<double>[1.0, -2.5, 3.75]))) {
+    throw StateError('VectorValue.isEqual() changed');
+  }
+  if (vector.isEqual(VectorValue(<double>[1.0]))) {
+    throw StateError('VectorValue.isEqual() length handling changed');
+  }
+}
+''';
+
+void main() {
+  late final Directory root;
+
+  setUpAll(() {
+    root = findRepositoryRoot();
+  });
+
+  test(
+    'VectorValue behavior compiles against the renamed entry point',
+    () async {
+      final result = await compileAndRunDartProbe(
+        root,
+        'rename_contract_vector_renamed',
+        _behaviorProbe.replaceAll(packageNameToken, renamedPackageName),
+      );
+      expect(
+        result.exitCode,
+        0,
+        reason:
+            'driving the preserved VectorValue behaviors through '
+            '`$renamedEntryPoint` must compile and succeed after the rename '
+            '(before it `$renamedEntryPoint` does not resolve and this '
+            'check fails compilation).\n'
+            'exit code: ${result.exitCode}\n'
+            'stdout:\n${result.stdout}\n'
+            'stderr:\n${result.stderr}',
+      );
+    },
+    timeout: const Timeout(Duration(minutes: 5)),
+  );
+}

