+      final String prompt = builder.systemPromptJoined();
+      expect(
+        prompt,
+        contains('com.example.my_catalog:orders.v2'),
+        reason:
+            'The prompt generated by PromptBuilder.custom must contain the '
+            'supplied non-empty catalog ID verbatim.',
+      );
+    });
+  });
 }

