+  // A genuine UTC instant: `toUtc()` returns the identical object and the
+  // `.toIso8601String()` text always ends in `Z`. These runtime properties
+  // - not any implementation's emitted source - distinguish the two
+  // serialization shapes the contract assertions accept.
+  final instant = DateTime.utc(2026, 8, 29, 10, 15, 22, 250);
+  if (!identical(instant.toUtc(), instant)) {
+    throw StateError(
+      'date_time_utc fixture assumption violated: toUtc() must return the '
+      'identical object for a genuine UTC instant',
+    );
+  }
+  final utcText = instant.toUtc().toIso8601String();
+  if (!utcText.endsWith('Z')) {
+    throw StateError(
+      'date_time_utc fixture assumption violated: the UTC serialization '
+      'must end in `Z`, got `$utcText`',
+    );
+  }
+  final plainText = instant.toIso8601String();
+  return DateTimeUtcShapes(utcText, plainText);
