+/// UTC serialization is ([utc] == true) or is not ([utc] == false) in
+/// effect, per the observable behavior the contract fixes.
+///
+/// This intentionally only describes the observable emission grammar -
+/// `source.toIso8601String()` and `source.toUtc().toIso8601String()` - so
+/// the assertions above accept freshly generated code of exactly those
+/// forms without pinning one implementation's formatting choices.
+String _emissionFor(String source, {required bool utc}) =>
+    utc ? '$source.toUtc().toIso8601String()' : '$source.toIso8601String()';
+
+/// The one local instant every execution assertion in the
+/// `date_time_utc generated serializer execution` group is built around.
+///
+/// It is a local (non-UTC) `DateTime` on every platform, so the plain
+/// (option-disabled) serialization [testInstantPlainText] and the
+/// required (option-enabled) serialization [testInstantUtcText] are
+/// different, unambiguous strings - the UTC text always ends in `Z`
+/// while the plain text never does.
+final testInstant = DateTime(2026, 8, 29, 12, 15, 22, 250);
+
+/// The exact text an executed `toJson` must produce for [testInstant]
+/// when the `dateTimeUtc` option is not in effect.
+final testInstantPlainText = testInstant.toIso8601String();
+
+/// The exact text an executed `toJson` must produce for [testInstant]
+/// when the `dateTimeUtc` option is in effect.
+final testInstantUtcText = testInstant.toUtc().toIso8601String();
+
+/// A matcher for the exact text an executed `toJson` must produce when it
+/// serializes [instant] with the `dateTimeUtc` option in effect
+/// ([utc] = `true`) or with the option not in effect ([utc] = `false`).
+///
+/// The expected text - and the presence or absence of the trailing `Z` -
+/// is computed from the `dart:core` DateTime API on the test platform at
+/// runtime; no emitted-source identifier, expression shape, or formatting
+/// choice of any implementation contributes to it, so the matcher accepts
+/// every runtime-correct implementation and rejects every runtime-wrong
+/// one.
+Matcher _utcShapeFor(DateTime instant, {required bool utc}) {
+  final expected = utc
+      ? instant.toUtc().toIso8601String()
+      : instant.toIso8601String();
+  return allOf(equals(expected), utc ? endsWith('Z') : isNot(endsWith('Z')));
