+import 'package:google_cloud_protobuf/protobuf.dart';
+import 'package:test/test.dart';
+
+void main() {
+  test('encode null', () {
+    expect(NullValue.nullValue.toJson(), null);
+  });
+
+  test('decode null', () {
+    // `NullValue.fromJson(null)` must return `NullValue.nullValue`. Asserting
+    // behavioral equivalence through repeated encoding (instead of equality
+    // against the `NullValue.nullValue` constant) keeps this test independent
+    // of how NullValue instances implement identity or equality.
+    expect(NullValue.fromJson(null).toJson(), null);
+    expect(
+      NullValue.fromJson(null).toJson(),
+      NullValue.nullValue.toJson(),
+    );
+  });
+}
