+// distributed under the License is distributed on an "AS IS" BASIS,
+// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+// See the License for the specific language governing permissions and
+// limitations under the License.
+
+import 'package:google_cloud_protobuf/protobuf.dart';
+import 'package:test/test.dart';
+
+void main() {
+  test('encode null', () {
+    expect(Value(nullValue: NullValue.nullValue).toJson(), null);
+  });
+
+  test('decode null', () {
+    // Decoding a JSON `null` must produce a null-holding value. Assert the
+    // observable round-trip JSON behavior (asserting the specific `nullValue`
+    // getter result would over-specify the contract).
+    expect(Value.fromJson(null).toJson(), null);
+  });
+
+  test('encode number', () {
+    expect(Value(numberValue: 1.5).toJson(), 1.5);
+  });
+
+  test('decode number', () {
+    expect(Value.fromJson(1.5).numberValue, 1.5);
+  });
+
+  test('decode int', () {
+    expect(Value.fromJson(1).numberValue, 1.0);
+  });
+
+  test('encode string', () {
+    expect(Value(stringValue: 'foo').toJson(), 'foo');
+  });
+
+  test('decode string', () {
+    expect(Value.fromJson('foo').stringValue, 'foo');
+  });
+
+  test('encode bool', () {
+    expect(Value(boolValue: true).toJson(), true);
+  });
+
+  test('decode bool', () {
+    expect(Value.fromJson(true).boolValue, true);
+  });
+
+  test('encode list', () {
+    expect(
+      Value(
+        listValue: ListValue(
+          values: [
+            Value(stringValue: 'foo'),
+            Value(nullValue: NullValue.nullValue),
+          ],
+        ),
+      ).toJson(),
+      ['foo', null],
+    );
+  });
+
+  test('decode list', () {
+    expect(Value.fromJson(['foo', null]).toJson(), ['foo', null]);
+  });
+
+  test('encode struct', () {
+    expect(
+      Value(
+        structValue: Struct(fields: {'foo': Value(stringValue: 'bar')}),
+      ).toJson(),
+      {'foo': 'bar'},
+    );
+  });
+
+  test('decode struct', () {
+    expect(
+      Value.fromJson({'foo': 'bar', 'baz': null}).toJson(),
+      {'foo': 'bar', 'baz': null},
+    );
+  });
+}
