FieldMask not correctly serialized using camelCase
From https://github.com/protocolbuffers/protobuf/blob/main/src/google/protobuf/field_mask.proto

```
// In JSON, a field mask is encoded as a single string where paths are
// separated by a comma. Fields name in each path are converted
// to/from lower-camel naming conventions.

```

test_patch:
diff --git a/generated/google_cloud_protobuf/test/fieldmask_test.dart b/generated/google_cloud_protobuf/test/fieldmask_test.dart
index 7c8c7fa..01fe939 100644
--- a/generated/google_cloud_protobuf/test/fieldmask_test.dart
+++ b/generated/google_cloud_protobuf/test/fieldmask_test.dart
@@ -31,21 +31,34 @@ void main() {
     expect(fieldMask.toJson(), 'one,two');
   });

+  test('encode snake_case to camelCase', () {
+    final fieldMask = FieldMask(paths: ['foo_bar', 'baz_qux.foo_bar']);
+    expect(fieldMask.toJson(), 'fooBar,bazQux.fooBar');
+  });
+
   test('decode empty', () {
     final fieldMask = FieldMask.fromJson('');
     final actual = fieldMask.paths.join('|');
     expect(actual, '');
   });

+  test('decode camelCase', () {
+    final fieldMask = FieldMask.fromJson('fooBar,bazQux.fooBar');
+    expect(fieldMask.paths, ['foo_bar', 'baz_qux.foo_bar']);
+  });
+
+  test('decode camelCase with all-caps word', () {
+    final fieldMask = FieldMask.fromJson('userHTTPRequest');
+    expect(fieldMask.paths, ['user_h_t_t_p_request']);
+  });
+
   test('decode single', () {
     final fieldMask = FieldMask.fromJson('one');
-    final actual = fieldMask.paths.join('|');
-    expect(actual, 'one');
+    expect(fieldMask.paths, ['one']);
