+    ignore (Room.add_task count_config ~title:"count-room-task" ~priority:3 ~description:"");

     let result = Room.rooms_list config in
     check (option int) "default counts only active tasks" (Some 1)
@@ -313,6 +320,78 @@ let test_legacy_masc_as_default_room () =
 (* Test Suite                                   *)
 (* ============================================ *)

+
+(* Regression: a config whose scope is [Default] must resolve to the
+   default (root) room even when the [current_room] file points at a
+   different room.  Scope resolution happens at config creation; only an
+   explicitly [Named] scope or [config_with_resolved_scope] follows the
+   current room.  Previously [masc_dir] re-read [current_room] on every
+   call, so a default-scope config silently read the wrong room. *)
+let test_default_scope_reads_default_room () =
+  let (config, test_dir) = setup_test_room () in
+  Fun.protect ~finally:(fun () -> cleanup_test_room test_dir) (fun () ->
+    ignore (Room.init config ~agent_name:None);
+    ignore (Room.add_task config ~title:"root-task" ~priority:3 ~description:"default room task");
+    check int "default room has one task" 1 (task_count config);
+
+    ignore (Room.room_create config ~name:"Isolated Room" ~description:None);
+    ignore (Room.room_enter config ~room_id:"isolated-room" ~agent_type:"codex" ());
+
+    (* [config] still has [Default] scope: it must keep reading the default
+       (root) room even though [current_room] now names "isolated-room". *)
+    check int "default-scope config reads default room" 1 (task_count config);
+  )
+
+(* Regression: a config resolved while a non-default room is the current
+   room keeps that room.  Later changes to the [current_room] file must not
+   move the already-resolved config to a different room. *)
+let test_resolved_scope_stable_after_room_switch () =
+  let (config, test_dir) = setup_test_room () in
+  Fun.protect ~finally:(fun () -> cleanup_test_room test_dir) (fun () ->
+    ignore (Room.init config ~agent_name:None);
+    ignore (Room.room_create config ~name:"Room A" ~description:None);
+    ignore (Room.room_enter config ~room_id:"room-a" ~agent_type:"codex" ());
+
+    (* Resolve the scope while "room-a" is the current room. *)
+    let room_a_config = Room.config_with_resolved_scope config in
+    ignore (Room.add_task room_a_config ~title:"room-a-task" ~priority:3 ~description:"");
+    check int "resolved config sees its room task" 1 (task_count room_a_config);
+
+    (* Switch the current room after the config was resolved. *)
+    ignore (Room.room_create config ~name:"Room B" ~description:None);
+    ignore (Room.room_enter config ~room_id:"room-b" ~agent_type:"codex" ());
+
+    (* The previously resolved config must stay in "room-a". *)
+    check int "resolved config stays in its room" 1 (task_count room_a_config);
+  )
+
+(* Regression: a fresh default configuration created while a non-default
+   room is the current room must still observe the default (root) room.
+   Binding to the room recorded as current is an explicit opt-in via
+   [Room.config_with_resolved_scope]; a plain [Room.default_config] call
+   must never implicitly bind to the current room. *)
+let test_default_created_after_room_enter_stays_default () =
+  let (config, test_dir) = setup_test_room () in
+  Fun.protect ~finally:(fun () -> cleanup_test_room test_dir) (fun () ->
+    ignore (Room.init config ~agent_name:None);
+    ignore (Room.add_task config ~title:"root-task" ~priority:3 ~description:"default room task");
+    ignore (Room.room_create config ~name:"Current Room" ~description:None);
+    ignore (Room.room_enter config ~room_id:"current-room" ~agent_type:"codex" ());
+
+    (* Construct a fresh default configuration for the same workspace while
+       "current-room" is recorded as the current room.  It must observe the
+       default (root) room, not the recorded current room. *)
+    let fresh_default = Room.default_config test_dir in
+    check int "fresh default config reads default room" 1 (task_count fresh_default);
+
+    (* The explicit opt-in observes the recorded current room instead. *)
+    let current_config = Room.config_with_resolved_scope config in
+    check int "explicitly resolved config sees current room" 0 (task_count current_config);
+    ignore (Room.add_task current_config ~title:"current-room-task" ~priority:3 ~description:"");
+    check int "explicitly resolved config sees current room task" 1 (task_count current_config);
+    check int "fresh default config still reads default room" 1 (task_count fresh_default);
+  )
+
 let () =
   run "Multi-Room" [
     "rooms_list", [
@@ -333,6 +412,9 @@ let () =
       test_case "join_in_room keeps current room" `Quick test_join_in_room_keeps_current_room;
       test_case "tasks are isolated per room" `Quick test_room_task_isolation;
       test_case "rooms_list task_count uses active tasks" `Quick test_rooms_list_task_count_active_only;
+      test_case "default scope reads default room" `Quick test_default_scope_reads_default_room;
+      test_case "resolved scope stays after room switch" `Quick test_resolved_scope_stable_after_room_switch;
+      test_case "fresh default config stays in default room" `Quick test_default_created_after_room_enter_stays_default;
     ];
     "backward_compat", [
       test_case "legacy masc as default" `Quick test_legacy_masc_as_default_room;

