+}
+
+BValue ___bsts_g_Bosatsu_l_Predef_l_not__Int(BValue a) {
+  // ~x = (-1 - x)
+  return bsts_integer_negate(bsts_integer_add(a, bsts_integer_from_int(1)));
+}
