+
+int bsts_float64_cmp_total(BValue left, BValue right) {
+  double l = bsts_float64_to_double(left);
+  double r = bsts_float64_to_double(right);
+  _Bool l_nan = isnan(l);
+  _Bool r_nan = isnan(r);
+  if (l_nan) {
+    if (r_nan) {
+      return 0;
+    }
+    return -1;
+  }
+  if (r_nan) {
+    return 1;
+  }
+  if (l < r) return -1;
+  if (l > r) return 1;
+  return 0;
