+
+BValue bsts_string_from_utf8_bytes_static(size_t len, char* bytes) {
+  BSTS_String* str = GC_malloc_atomic(sizeof(BSTS_String));
+  str->len = len;
+  str->offset = 0;
+  if (len == 0 && bytes == NULL) {
+    str->bytes = bsts_empty_string_bytes;
+  }
+  else {
+    str->bytes = bytes;
+  }
+  return (BValue)str;
+}
