@@ -0,0 +1,326 @@
+// Copyright The OpenTelemetry Authors
+// SPDX-License-Identifier: Apache-2.0
+
+/// Governance tests ensuring the hand-maintained Dart sources carry the CNCF
+/// community-ownership copyright header required for transfer of this
+/// repository to the `open-telemetry` GitHub organization.
+library;
+
+import 'dart:io';
+
+import 'package:test/test.dart';
+
+/// The text that declares CNCF community ownership on a copyright line.
+const _ownershipText = 'Copyright The OpenTelemetry Authors';
+
+/// The project trees whose Dart sources are swept by the governance header
+/// update. The `test/` suite sources and loose root-level scratch scripts
+/// (for example `test_lambda_comparison.dart` and `test_otel_log.dart`) are
+/// intentionally outside this sweep.
+const _sourceRoots = ['lib', 'example', 'tool'];
+
+/// Generated sources are not hand-maintained, so they are exempt from the
+/// copyright sweep. The protobuf sources under `lib/proto` are produced by
+/// `tool/setup_protos.sh` and are omitted from coverage (see `.coveragerc`).
+bool _isGeneratedPath(String relativePath) =>
+    relativePath == 'lib/proto' || relativePath.startsWith('lib/proto/');
+
+/// Individual source files that are deliberately maintained as-is and are
+/// exempt from the header sweep. They must remain exactly identical to their
+/// declared expected contents: any edit, not only the addition of the CNCF
+/// ownership text, is a violation. The value for each path is the SHA-256
+/// hex digest of the file's exact required contents, an immutable anchor
+/// pinning what "maintained as-is" means for that file.
+const _exemptFiles = {
+  // Hand-maintained helper that retains its `Dartastic.io` copyright.
+  'lib/testing.dart':
+      '7877a65fe59a07adcceb9462c749caeabdedb2a081dd780e118cdf73ba2bacf9',
+  // Test-only export helper that retains its original notice.
+  'lib/src/trace/export/test_file_exporter.dart':
+      '2b31938f9d3977438efd8f300fc65f88cd753cda1a412113ee76e9d69f25430c',
+  // Smoke script retained verbatim for local Grafana smoke testing.
+  'example/grafana/grafana_smoke_test.dart':
+      '4e804bd02f40c1392f19571e420bf433b873ea41a480f8b94cab2958f2c068e6',
+};
+
+/// Tool scripts must remain directly executable: a shebang, when present,
+/// stays on the first line and the copyright header follows it.
+const _shebangScripts = [
+  'tool/read_all_env_vars.dart',
+  'tool/read_env_vars.dart',
+  'tool/read_otel_config.dart',
+];
+
+/// Recursively collects the paths, relative to the repository root, of every
+/// `.dart` file in the project source trees. Whether to recurse into a
+/// directory is decided from that directory's own basename: a directory
+/// whose own name begins with `.` is never descended into, whatever its
+/// position in the tree, so a nested hidden directory such as
+/// `lib/sub/.hidden` excludes everything beneath it.
+List<String> _dartSourceFiles() {
+  final rootPath = Directory.current.absolute.path;
+  final files = <String>[];
+  final pending = <Directory>[
+    for (final root in _sourceRoots) Directory('$rootPath/$root'),
+  ];
+
+  while (pending.isNotEmpty) {
+    final directory = pending.removeLast();
+    if (!directory.existsSync()) {
+      continue;
+    }
+    for (final entity in directory.listSync(followLinks: false)) {
+      final path = entity.absolute.path.replaceAll('\\', '/');
+      final relativePath = path.startsWith('$rootPath/')
+          ? path.substring(rootPath.length + 1)
+          : path;
+      final basename = relativePath.split('/').last;
+
+      if (entity is Directory) {
+        if (entity is! Link && !basename.startsWith('.')) {
+          pending.add(entity);
+        }
+      } else if (entity is File && relativePath.endsWith('.dart')) {
+        files.add(relativePath);
+      }
+    }
+  }
+
+  files.sort();
+  return files;
+}
+
+/// The in-scope files: discovered Dart sources minus generated and exempted
+/// ones.
+List<String> _checkedFiles() => [
+      for (final file in _dartSourceFiles())
+        if (!_isGeneratedPath(file) && !_exemptFiles.containsKey(file)) file,
+    ];
+
+/// The leading comment block of a file: an optional shebang line, any blank
+/// lines that follow it, then the run of `//` comment lines that introduces
+/// the file. The copyright declaration must live in this block, not deeper
+/// in the body.
+List<String> _headerLines(String contents) {
+  final lines = contents.split('\n');
+  var index = 0;
+  if (index < lines.length && lines[index].startsWith('#!')) {
+    index++;
+  }
+  while (index < lines.length && lines[index].trim().isEmpty) {
+    index++;
+  }
+  final header = <String>[];
+  while (index < lines.length && lines[index].startsWith('//')) {
+    header.add(lines[index]);
+    index++;
+  }
+  return header;
