+
+/// True when [line] carries a copyright declaration.
+bool _isCopyrightLine(String line) => line.contains('Copyright');
+
+/// True when [line] declares CNCF community ownership.
+bool _isOwnershipLine(String line) =>
+    _isCopyrightLine(line) && line.contains(_ownershipText);
