+
+    var a = hash[0];
+    var b = hash[1];
+    var c = hash[2];
+    var d = hash[3];
+    var e = hash[4];
+    var f = hash[5];
+    var g = hash[6];
+    var h = hash[7];
+
+    for (var t = 0; t < 64; t++) {
+      final s1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
+      final choose = (e & f) ^ (((~e) & 0xffffffff) & g);
+      final temp1 = (h + s1 + choose + _sha256RoundConstants[t] + schedule[t]) &
+          0xffffffff;
+      final s0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
+      final majority = (a & b) ^ (a & c) ^ (b & c);
+      final temp2 = (s0 + majority) & 0xffffffff;
+      h = g;
+      g = f;
+      f = e;
+      e = (d + temp1) & 0xffffffff;
+      d = c;
+      c = b;
+      b = a;
+      a = (temp1 + temp2) & 0xffffffff;
+    }
+
+    hash[0] = (hash[0] + a) & 0xffffffff;
+    hash[1] = (hash[1] + b) & 0xffffffff;
+    hash[2] = (hash[2] + c) & 0xffffffff;
+    hash[3] = (hash[3] + d) & 0xffffffff;
+    hash[4] = (hash[4] + e) & 0xffffffff;
+    hash[5] = (hash[5] + f) & 0xffffffff;
+    hash[6] = (hash[6] + g) & 0xffffffff;
+    hash[7] = (hash[7] + h) & 0xffffffff;
+  }
+
+  return hash.map((word) => word.toRadixString(16).padLeft(8, '0')).join();
+}
+
+/// The SHA-256 hex digest of a file's exact contents.
+String _fileDigest(String path) => _sha256Hex(File(path).readAsBytesSync());
+
+void main() {
+  group('CNCF copyright headers', () {
+    test('repository contains Dart source files', () {
+      expect(_dartSourceFiles(), isNotEmpty);
+    });
+
+    for (final root in _sourceRoots) {
+      test(
+          'every non-generated .dart source file in $root/ declares CNCF '
+          'community ownership', () {
+        final checked = <String>[];
+        final missing = <String>[];
+        final stale = <String>[];
+
+        for (final file in _checkedFiles()) {
+          if (!file.startsWith('$root/')) {
+            continue;
+          }
+          checked.add(file);
+          final header = _headerLines(File(file).readAsStringSync());
+          if (!header.any(_isOwnershipLine)) {
+            missing.add(file);
+          } else if (header.any(
+            (line) => _isCopyrightLine(line) && !_isOwnershipLine(line),
+          )) {
+            stale.add(file);
+          }
+        }
+
+        expect(
+          checked,
+          isNotEmpty,
+          reason: 'expected to find maintained .dart source files under '
+              '$root/',
+        );
+        expect(
+          missing,
+          isEmpty,
+          reason: 'every maintained .dart source file in $root/ must '
+              'carry a copyright line declaring CNCF community ownership '
+              '(`$_ownershipText`, see https://github.com/cncf/'
+              'foundation/blob/main/copyright-notices.md) in its leading '
+              'comment block, but these files do not:\n  '
+              '${missing.join('\n  ')}',
+        );
+        expect(
+          stale,
+          isEmpty,
+          reason: 'the leading copyright block must not retain any other '
+              'copyright declaration alongside `$_ownershipText`, but '
+              'these files do:\n  '
+              '${stale.join('\n  ')}',
+        );
+      });
+    }
+
+    test('exempt sources are maintained as-is', () {
+      final violated = <String>[];
+
+      for (final entry in _exemptFiles.entries) {
+        final file = File(entry.key);
+        if (!file.existsSync() || _fileDigest(entry.key) != entry.value) {
+          violated.add(entry.key);
+        }
+      }
+
+      expect(
+        violated,
+        isEmpty,
+        reason: 'exempt sources sit outside the header sweep: they must be '
+            'maintained exactly as-is (their contents must match the '
+            'recorded digests) and must not gain `$_ownershipText`, but '
+            'these files were changed:\n  '
+            '${violated.join('\n  ')}',
+      );
+    });
+
+    test('tool scripts keep a shebang on the first line', () {
+      final misplaced = <String>[];
+
+      for (final file in _shebangScripts) {
+        if (!File(file).readAsStringSync().startsWith('#!')) {
+          misplaced.add(file);
+        }
+      }
+
+      expect(
+        misplaced,
+        isEmpty,
+        reason: 'executable tool scripts must keep `#!` on the first line '
+            'with the copyright header following it, but these do not:\n  '
+            '${misplaced.join('\n  ')}',
+      );
+    });
+  });
+}

problem_statement:
feat: Ktor Application/Route extensions
Allow installing Mokksy to as Ktor [application module](
https://ktor.io/docs/server-modules.html#defining-a-module), e.g.:

```kotlin
fun Application.mokksy(path: String) {
    ...
}
```

Or as Route extension, e.g. to support Ktor authentication:

```kotlin
embeddedServer(...) {
    //configurePlugins()
    // installBasicAuth()
    routing {
        authenticate(AUTH_REALM) {
            mokksy()
        }
    }
```

### Additional contract requirements

The Ktor embedding API is provided by two Kotlin extension overloads named `mokksy`: one on `io.ktor.server.application.Application` and one on `io.ktor.server.routing.Route`. Both accept `server: MokksyHandler` and `path: String = "{...}"`, and return `Unit`. `MokksyServer` implements the `MokksyHandler` abstraction, which exposes the server configuration and handles an incoming Ktor routing context.

The application-scoped overload installs SSE, DoubleReceive, and ContentNegotiation using the handler's server configuration before mounting request handling. The route-scoped overload does not install application-level plugins: when it is the only mount in the application, SSE, DoubleReceive, and ContentNegotiation remain uninstalled, so callers using it are responsible for configuring those plugins on the surrounding application.

The default path serves matching stubs in the application or route scope and leaves unmatched requests as 404 Not Found. A custom pattern such as `"/api/{...}"` limits handling to that mount prefix for either overload, so stubs outside the prefix are not reachable through the mount and requests outside the prefix remain 404 Not Found. A route-scoped mount can be nested inside authentication or other middleware: matching authenticated requests are served, while unauthenticated requests are rejected by the enclosing middleware.

