diff --git a/test/nahpu_shell_test.dart b/test/nahpu_shell_test.dart
new file mode 100644
index 00000000..90e046d7
--- /dev/null
+++ b/test/nahpu_shell_test.dart
@@ -0,0 +1,339 @@
+import 'package:drift/drift.dart' show DatabaseConnection, Value;
+import 'package:drift/native.dart';
+import 'package:flutter/material.dart';
+import 'package:flutter_riverpod/flutter_riverpod.dart';
+import 'package:flutter_test/flutter_test.dart';
+import 'package:nahpu/screens/home/home.dart';
+import 'package:nahpu/screens/shared/navigation.dart';
+import 'package:nahpu/services/database/database.dart';
+import 'package:nahpu/services/database/project_queries.dart';
+import 'package:nahpu/services/providers/database.dart';
+import 'package:nahpu/services/providers/settings.dart';
+import 'package:shared_preferences/shared_preferences.dart';
+
+/// Contract tests for the project's top-level bottom navigation.
+///
+/// The reported problem: tapping a destination in the project's bottom
+/// navigation bar triggered a full-screen page transition — visually
+/// signaling "going deeper" instead of switching sections — and discarded
+/// the visible section's state (scroll positions, expanded panels, and the
+/// like) on every switch. The navbar's destination-indicator animation also
+/// ran for a sluggish three seconds.
+///
+/// These tests drive the real application surfaces. Each behavior test
+/// launches the app's home screen, opens a project exactly the way a user
+/// does, taps the real `ProjectBottomNavbar` destinations, and observes the
+/// real section content — the Dashboard, Sites, Events, Specimens, and
+/// Narrative viewers — responding to the taps:
+///
+///  * every destination tap must swap the visible top-level section in
+///    place, without pushing or replacing any full-screen route;
+///  * an already-visited section's content must remain alive off stage
+///    while another section is shown, so the section's state survives the
+///    round trip away and back;
+///  * the destination-indicator animation must be reduced from the
+///    three-second value.
+///
+/// The observations are deliberately mechanism-agnostic: no assertion names
+/// an internal widget, provider, or state-management realization. Any
+/// implementation that keeps every top-level section alive in place while
+/// swapping the visible content without a route change satisfies the
+/// contract.
+
+const String _projectUuid = 'proj-navbar-contract';
+const String _projectName = 'Navbar contract project';
+
+Future<Database> _openTestDatabase() async {
+  final db = Database.forTesting(DatabaseConnection(NativeDatabase.memory()));
+  addTearDown(db.close);
+  await ProjectQuery(db).createProject(const ProjectCompanion(
+    uuid: Value(_projectUuid),
+    name: Value(_projectName),
+  ));
+  return db;
+}
+
+ProviderContainer _appContainer(Database db, SharedPreferences prefs) {
+  final container = ProviderContainer(
+    overrides: [
+      databaseProvider.overrideWithValue(db),
+      settingProvider.overrideWithValue(prefs),
+    ],
+  );
+  addTearDown(container.dispose);
+  return container;
+}
+
+/// Records every full-screen route change the app performs while the user
+/// interacts with it.
+class _RouteChangeObserver extends NavigatorObserver {
+  int pushes = 0;
+  int replacements = 0;
+
+  @override
+  void didPush(Route<dynamic> route, Route<dynamic>? previousRoute) {
+    pushes++;
+  }
+
+  @override
+  void didReplace({Route<dynamic>? newRoute, Route<dynamic>? oldRoute}) {
+    replacements++;
+  }
+}
+
+class _RouteChangeCounts {
+  const _RouteChangeCounts(this.pushes, this.replacements);
+
+  final int pushes;
+  final int replacements;
+}
+
+_RouteChangeCounts _countsOf(_RouteChangeObserver observer) =>
+    _RouteChangeCounts(observer.pushes, observer.replacements);
+
+/// Runs a widget test with the layout overflow reports of the real sections
+/// silenced: the sections laid out below the navigation bar report their
+/// overflow on narrow test surfaces, and those reports are not part of the
+/// behavior under observation.
+Future<void> _runShellTest(
+  WidgetTester tester,
+  Future<void> Function() body,
+) async {
+  final originalOnError = FlutterError.onError;
+  FlutterError.onError = (details) {
+    if (details.exceptionAsString().contains('overflowed')) {
+      return;
+    }
+    originalOnError?.call(details);
+  };
+  addTearDown(() {
+    FlutterError.onError = originalOnError;
+  });
+  await body();
+}
+
+/// Pumps the real application entry surface with the seeded project and the
+/// route-change observer attached, then opens the project the way a user
+/// does: by tapping its card. Lands on the project's Dashboard section.
+Future<_RouteChangeObserver> _openProject(WidgetTester tester) async {
+  final db = await _openTestDatabase();
+  final prefs = await SharedPreferences.getInstance();
+  final container = _appContainer(db, prefs);
+  final observer = _RouteChangeObserver();
+
+  await tester.pumpWidget(
+    UncontrolledProviderScope(
+      container: container,
+      child: MaterialApp(
+        scrollBehavior: const MaterialScrollBehavior(),
+        navigatorObservers: [observer],
+        home: const Home(),
+      ),
+    ),
+  );
+  await tester.pumpAndSettle();
+
+  await tester.tap(find.text(_projectName));
+  await tester.pumpAndSettle();
+  return observer;
+}
+
+/// The bottom navigation bar is laid out below the section app bars on
+/// narrow test surfaces; the small navigation bar and the app bars share
+/// the padded viewport, so a plain [tester.tap] on the destination label
+/// can hit the app bar instead. The real destinations stay reachable
+/// because the [NavigationBar] sizes itself to its destinations and its
+/// bottom edge stays unobstructed: tapping near a destination's bottom
+/// edge below the section app bar hits the real destination.
+Future<void> _tapDestination(WidgetTester tester, String label) async {
+  final appBarBottom = tester.getTopLeft(find.byType(AppBar).last).dy +
+      tester.getSize(find.byType(AppBar).last).height;
+  final navTop = tester.getTopLeft(find.byType(NavigationBar)).dy;
+  final labelCenter = tester.getCenter(
+    find.descendant(
+      of: find.byType(ProjectBottomNavbar),
+      matching: find.text(label),
+    ),
+  );
+  final tapY = _mathMax(
+    labelCenter.dy,
+    appBarBottom + (navTop - appBarBottom) / 2,
+  );
+  await tester.tapAt(Offset(labelCenter.dx, tapY));
+  await tester.pumpAndSettle();
+}
+
+double _mathMax(double a, double b) => a > b ? a : b;
+
+/// Asserts that an app-bar with [title] is actually shown on stage. A
+/// destination swap manifests as the on-stage section `AppBar` title, but
+/// the tree may legitimately hold additional `Text(title)` widgets: every
+/// visited section stays alive off stage, different valid shells keep one
+/// or several `ProjectBottomNavbar`s in the tree, and an off-stage
+/// navigation bar may still render its destination labels. The whole-tree
+/// text count is therefore not part of the contract; what is observable is
+/// the on-stage section title.
+void _expectOnstageSectionTitle(String title, {String? reason}) {
+  expect(
+    find.ancestor(
+      of: find.text(title),
+      matching: find.byType(AppBar),
+    ),
+    findsAtLeastNWidgets(1),
+    reason: reason ??
+        'an on-stage section app bar must show "$title" after the '
+            'destination swap',
+  );
+}
+
+/// Asserts that the section identified by its app-bar [title] text remains
+/// present in the tree, whether its content is currently shown or retained
+/// off stage. The matcher is deliberately a minimum rather than an exact
+/// count: valid implementations keep different numbers of navigation bars
+/// and section scaffolds in the tree, so only the continued existence of
+/// the section's content is contractual, never its widget multiplicity.
+void _expectSectionContentAlive(String title, {String? reason}) {
+  expect(
+    find.text(title, skipOffstage: false),
+    findsWidgets,
+    reason: reason ??
+        'the $title section content must stay in the tree, on stage or '
+            'off stage',
+  );
+}
+
+void main() {
+  TestWidgetsFlutterBinding.ensureInitialized();
+
+  setUp(() {
+    SharedPreferences.setMockInitialValues({});
+  });
+
+  group('project top-level destination switching, on the real app surface',
+      () {
+    testWidgets(
+        'tapping a destination swaps the visible section in place without '
+        'pushing or replacing a route', (tester) async {
+      await _runShellTest(tester, () async {
+        final observer = await _openProject(tester);
+
+        _expectOnstageSectionTitle('Project Dashboard',
+            reason: 'opening a project lands on its Dashboard section');
+
+        final before = _countsOf(observer);
+
+        await _tapDestination(tester, 'Sites');
+
+        _expectOnstageSectionTitle('Sites',
+            reason: 'tapping the Sites destination must swap the visible '
+                'section in place, so the Sites section title is the one '
+                'shown on stage');
+        _expectSectionContentAlive('Project Dashboard',
+            reason: 'the previously visible Dashboard section content must '
+                'stay in the tree, retained off stage, instead of being '
+                'discarded with a route');
+        final after = _countsOf(observer);
+        expect(after.pushes - before.pushes, 0,
+            reason: 'a top-level destination tap must not push a '
+                'full-screen route');
+        expect(after.replacements - before.replacements, 0,
+            reason: 'a top-level destination tap must not replace the '
+                'route the user is on; the content swap must happen in '
+                'place');
+
+        await _tapDestination(tester, 'Dashboard');
+
+        _expectOnstageSectionTitle('Project Dashboard',
+            reason: 'switching back returns to the previously visible '
+                'section');
+        _expectSectionContentAlive('Sites',
+            reason: 'the just-visited Sites section stays alive in the '
+                'tree, retained off stage, so its state survives the '
+                'switch away and back');
+
+      });
+    });
+
+    testWidgets(
+        'every destination switches in place and keeps visited sections '
+        'alive', (tester) async {
+      await _runShellTest(tester, () async {
+        final observer = await _openProject(tester);
+
+        _expectOnstageSectionTitle('Project Dashboard',
+            reason: 'opening a project lands on its Dashboard section');
+
+        final before = _countsOf(observer);
+
+        const destinations = <String, String>{
+          'Sites': 'Sites',
+          'Events': 'Events',
+          'Specimens': 'Specimen Records',
+          'Narrative': 'Narrative',
+          'Dashboard': 'Project Dashboard',
+        };
+        final visitedTitles = <String>['Project Dashboard'];
+
+        for (final entry in destinations.entries) {
+          await _tapDestination(tester, entry.key);
+          visitedTitles.add(entry.value);
+
+          // The tapped destination must show its own section on stage,
+          // and every previously visited section must stay alive in the
+          // tree (off stage) instead of being discarded with a route.
+          _expectOnstageSectionTitle(entry.value,
+              reason: 'tapping the ${entry.key} destination must swap the '
+                  'visible section in place, so the ${entry.value} section '
+                  'title is the one shown on stage');
+          for (final title in visitedTitles) {
+            _expectSectionContentAlive(title,
+                reason: 'the $title section content must stay in the tree '
+                    '(off stage once another section is shown) after '
+                    'tapping ${entry.key}');
+          }
+        }
+
+        final after = _countsOf(observer);
+        expect(after.pushes - before.pushes, 0,
+            reason: 'no top-level destination tap may push a full-screen '
+                'route');
+        expect(after.replacements - before.replacements, 0,
+            reason: 'no top-level destination tap may replace the route '
+                'the user is on; every content swap must happen in place');
+        expect(find.byType(ProjectBottomNavbar), findsOneWidget,
+            reason: 'the user is still on the project section screen after '
+                'visiting every destination');
+      });
+    });
+  });
+
+  group('bottom navigation bar appearance', () {
+    testWidgets('the destination indicator animation is reduced from the '
+        'three-second default', (tester) async {
+      final db = await _openTestDatabase();
+      final prefs = await SharedPreferences.getInstance();
+      final container = _appContainer(db, prefs);
+
+      await tester.pumpWidget(
+        UncontrolledProviderScope(
+          container: container,
+          child: const MaterialApp(
+            home: Scaffold(
+              bottomNavigationBar: ProjectBottomNavbar(),
+            ),
+          ),
+        ),
+      );
+      await tester.pump();
+
+      final navBar = tester.widget<NavigationBar>(find.byType(NavigationBar));
+      expect(
+          navBar.animationDuration,
+          anyOf(isNull, lessThan(const Duration(seconds: 3))),
+          reason: 'the destination-indicator animation ran for three '
+              'seconds, which feels sluggish for a top-level switch; it must '
+              'complete in less than three seconds');
+      expect(find.byType(ProjectBottomNavbar), findsOneWidget);
+    });
+  });
+}
