diff --git a/compiler/lib/src/test/scala/semantics/ShiftValueSpec.scala b/compiler/lib/src/test/scala/semantics/ShiftValueSpec.scala
new file mode 100644
index 000000000..c6b92b4e6
--- /dev/null
+++ b/compiler/lib/src/test/scala/semantics/ShiftValueSpec.scala
@@ -0,0 +1,143 @@
+package fpp.compiler.test
+
+import fpp.compiler.analysis._
+import fpp.compiler.ast._
+import fpp.compiler.syntax.Parser
+import fpp.compiler.util.Result
+import org.scalatest.wordspec.AnyWordSpec
+
+/** End-to-end tests for numeric shift expressions (<</>>) in FPP source.
+  *
+  * Shift support is a user-visible language feature (see the issue "Support
+  * shift operations for numeric values"): users write shift expressions such
+  * as `0x7F << SomeBytePatternOffset` in FPP files. These tests exercise the
+  * feature through the public language surface only: they parse FPP source
+  * text and check the source-level semantics of the parsed model. They do
+  * not depend on any particular internal representation of the feature.
+  */
+class ShiftValueSpec extends AnyWordSpec {
+
+  /** Parse an FPP translation unit from source text and check its
+    * source-level semantics. Returns the parsed unit and resulting analysis.
+    */
+  private def analyzeSource(source: String): Result.Result[(Ast.TransUnit, Analysis)] =
+    for {
+      tu <- Parser.parseString(Parser.transUnit)(source)
+      a <- CheckSemantics.tuList(Analysis(), List(tu))
+    } yield (tu, a)
+
+  /** Analyze FPP source that is expected to be semantically valid and
+    * return the value computed for the top-level constant with the given
+    * name.
+    */
+  private def evaluatedConstantValue(source: String, name: String): Value = {
+    val (tu, a) = analyzeSource(source) match {
+      case Right(pair) => pair
+      case Left(err) => fail(s"expected well-formed model, got error: ${err.toString}")
+    }
+    val matchingNodes = tu.members.collect {
+      case Ast.ModuleMember((_, Ast.ModuleMember.DefConstant(node), _))
+        if node.data.name == name => node
+    }
+    assert(matchingNodes.length == 1, s"expected exactly one top-level constant $name")
+    val node = matchingNodes.head
+    a.valueMap.get(node.id) match {
+      case Some(v) => v
+      case None => fail(s"constant $name has no computed value")
+    }
+  }
+
+  /** Assert that the evaluation of the constant `name` defined in `source`
+    * yields an integer value equal to `expected`.
+    */
+  private def assertConstantIntValue(source: String, name: String, expected: BigInt): Unit =
+    evaluatedConstantValue(source, name) match {
+      case Value.PrimitiveInt(v, _) => assert(v == expected)
+      case Value.Integer(v) => assert(v == expected)
+      case v => fail(s"constant $name did not evaluate to an integer value: $v")
+    }
+
+  /** Assert that the FPP source is rejected during parsing or semantic checks */
+  private def assertRejected(source: String): Unit =
+    analyzeSource(source) match {
+      case Left(_) => ()
+      case Right(_) => fail(s"expected the model to be rejected:\n$source")
+    }
+
+  private val issueExample = """
+constant SomeBytePatternOffset = 4
+constant SomeBytePatternMask = 0x7F << SomeBytePatternOffset
+"""
+
+  "the example from the issue" should {
+    "evaluate a byte-pattern mask defined with a left shift" in {
+      assertConstantIntValue(issueExample, "SomeBytePatternMask", BigInt("7F", 16) << 4)
+    }
+  }
+
+  "left shift (<<)" should {
+    val rows = List(
+      ("constant r = 2 << 3", BigInt(16), "literal operands"),
+      ("constant r = 8 << 0", BigInt(8), "zero shift amount leaves the value unchanged"),
+      ("constant r = 1 << 255", BigInt(1) << 255, "the largest allowed shift amount"),
+      ("constant n = 2\nconstant r = n << 3", BigInt(16), "a constant as the shifted value"),
+      ("constant r = 1 + 2 << 2", BigInt(12), "addition binds tighter than a shift"),
+      ("constant r = 1 << 2 + 1", BigInt(8), "the shift amount may be an additive expression"),
+      ("constant r = 1 << (4 - 2)", BigInt(4), "the shift amount may be a parenthesized expression"),
+      ("constant r = 1 << 1 << 3", BigInt(16), "chained shifts associate to the left"),
+      ("enum E { X }\nconstant r = E.X << 1", BigInt(0), "an enum-typed value is shifted via its representation value"),
+      ("constant r = -8 << 1", BigInt(-16), "a negative value may be left-shifted"),
+      ("enum E: I32 { X = 1 }\nconstant r = E.X << 3", BigInt(8), "an enum with a primitive integer representation type may be shifted"),
+    )
+    rows.foreach { row =>
+      s"evaluate ${row._1.split('\n').last} (${row._3})" in
+        assertConstantIntValue(row._1, "r", row._2)
+    }
+    "reject a floating-point shifted value" in {
+      assertRejected("constant r = 1.0 << 2")
+    }
+    "reject a floating-point shift amount" in {
+      assertRejected("constant r = 1 << 2.0")
+    }
+    "reject a string operand" in {
+      assertRejected("""constant r = "a" << 1""")
+    }
+    "reject a Boolean operand" in {
+      assertRejected("constant r = true << 1")
+    }
+    "reject a negative shift amount" in {
+      assertRejected("constant r = 1 << -1")
+    }
+    "reject a shift amount greater than 255" in {
+      assertRejected("constant r = 1 << 256")
+    }
+  }
+
+  "right shift (>>)" should {
+    val rows = List(
+      ("constant r = 8 >> 2", BigInt(2), "literal operands"),
+      ("constant r = 8 >> 0", BigInt(8), "zero shift amount leaves the value unchanged"),
+      ("constant r = -8 >> 2", BigInt(-2), "right shift is signed, equivalent to floor division by a power of two"),
+      ("enum E { X }\nconstant r = E.X >> 1", BigInt(0), "an enum-typed value is shifted via its representation value"),
+      ("constant r = 256 >> 4 >> 2", BigInt(4), "chained shifts associate to the left"),
+      ("constant r = 1 + 8 >> 2", BigInt(2), "addition binds tighter than a shift"),
+    )
+    rows.foreach { row =>
+      s"evaluate ${row._1.split('\n').last} (${row._3})" in
+        assertConstantIntValue(row._1, "r", row._2)
+    }
+    "reject a floating-point shifted value" in {
+      assertRejected("constant r = 16.0 >> 1")
+    }
+    "reject a floating-point shift amount" in {
+      assertRejected("constant r = 16 >> 1.0")
+    }
+    "reject a negative shift amount" in {
+      assertRejected("constant r = 16 >> -1")
+    }
+    "reject a shift amount greater than 255" in {
+      assertRejected("constant r = 16 >> 256")
+    }
+  }
+
+}

