diff --git a/test/get_time_ago_test.dart b/test/get_time_ago_test.dart
index 21b0f53..4aefa0f 100644
--- a/test/get_time_ago_test.dart
+++ b/test/get_time_ago_test.dart
@@ -90,5 +90,95 @@ void main() {
       final result = GetTimeAgo.parse(dateTime, locale: 'test');
       expect(result, equals('3 mins ago'));
     });
+
+    test('Test future date (less than 15 seconds)', () {
+      GetTimeAgo.setDefaultLocale('en');
+      final dateTime = DateTime.now().add(const Duration(seconds: 10));
+      final result = GetTimeAgo.parse(dateTime);
+      expect(result, matches(r'^in\s'));
+      expect(result, isNot(equals('just now')));
+    });
+
+    test('Test future date (seconds)', () {
+      GetTimeAgo.setDefaultLocale('en');
+      final dateTime = DateTime.now().add(const Duration(seconds: 45));
+      final result = GetTimeAgo.parse(dateTime);
+      expect(result, matches(r'^in\s'));
+    });
+
+    test('Test future date (about a minute)', () {
+      GetTimeAgo.setDefaultLocale('en');
+      final dateTime =
+          DateTime.now().add(const Duration(seconds: 90));
+      final result = GetTimeAgo.parse(dateTime);
+      expect(result, matches(r'^in\s'));
+    });
+
+    test('Test future date (minutes)', () {
+      GetTimeAgo.setDefaultLocale('en');
+      final dateTime = DateTime.now().add(const Duration(minutes: 30));
+      final result = GetTimeAgo.parse(dateTime);
+      expect(result, matches(r'^in\s'));
+    });
+
+    test('Test future date (about an hour)', () {
+      GetTimeAgo.setDefaultLocale('en');
+      final dateTime = DateTime.now().add(const Duration(minutes: 70));
+      final result = GetTimeAgo.parse(dateTime);
+      expect(result, matches(r'^in\s'));
+    });
+
+    test('Test future date (hours)', () {
+      GetTimeAgo.setDefaultLocale('en');
+      final dateTime = DateTime.now().add(const Duration(hours: 5));
+      final result = GetTimeAgo.parse(dateTime);
+      expect(result, matches(r'^in\s'));
+    });
+
+    test('Test future date (about a day)', () {
+      GetTimeAgo.setDefaultLocale('en');
+      final dateTime = DateTime.now().add(const Duration(hours: 36));
+      final result = GetTimeAgo.parse(dateTime);
+      expect(result, matches(r'^in\s'));
+    });
+
+    test('Test future date (days)', () {
+      GetTimeAgo.setDefaultLocale('en');
+      final dateTime = DateTime.now().add(const Duration(days: 5));
+      final result = GetTimeAgo.parse(dateTime);
+      expect(result, matches(r'^in\s'));
+    });
+
+    test('Test future date (French locale)', () {
+      final dateTime = DateTime.now().add(const Duration(minutes: 30));
+      GetTimeAgo.setDefaultLocale('fr');
+      final pastResult =
+          GetTimeAgo.parse(
+              DateTime.now().subtract(const Duration(minutes: 30)));
+      final futureResult = GetTimeAgo.parse(dateTime);
+      expect(futureResult, isNot(contains('il y a')));
+      expect(futureResult, isNot(equals(pastResult)));
+    });
+
+    test('Test future date (custom locale is not past-style)', () {
+      GetTimeAgo.setCustomLocaleMessages('test', CustomLocaleTestMessages());
+      final dateTime = DateTime.now().add(const Duration(minutes: 30));
+      final pastResult =
+          GetTimeAgo.parse(
+              DateTime.now().subtract(const Duration(minutes: 30)),
+              locale: 'test');
+      final futureResult = GetTimeAgo.parse(dateTime, locale: 'test');
+      expect(futureResult, isNot(contains('ago')));
+      expect(futureResult, isNot(equals(pastResult)));
+    });
+
+    test('Test past and future dates are distinguishable', () {
+      GetTimeAgo.setDefaultLocale('en');
+      final futureResult =
+          GetTimeAgo.parse(DateTime.now().add(const Duration(days: 10)));
+      final pastResult =
+          GetTimeAgo.parse(DateTime.now().subtract(const Duration(days: 10)));
+      expect(futureResult, isNot(equals(pastResult)));
+    });
   });
 }

