test_patch:
diff --git a/test/sbb_toast_text_theme_test.dart b/test/sbb_toast_text_theme_test.dart
new file mode 100644
index 0000000..c224472
--- /dev/null
+++ b/test/sbb_toast_text_theme_test.dart
@@ -0,0 +1,89 @@
+import 'package:flutter/material.dart';
+import 'package:flutter_test/flutter_test.dart';
+import 'package:sbb_design_system_mobile/sbb_design_system_mobile.dart';
+
+void main() {
+  ThemeData themeWithCustomizedTextTheme({
+    required Brightness brightness,
+    TextStyle? smallLight,
+    TextStyle? smallBold,
+  }) {
+    final base = brightness == .light ? SBBTheme.light() : SBBTheme.dark();
+    final baseStyle = base.sbbBaseStyle;
+    final customizedTextTheme = baseStyle.textTheme.copyWith(smallLight: smallLight, smallBold: smallBold);
+    final customizedBaseStyle = baseStyle.copyWith(textTheme: customizedTextTheme) as SBBBaseStyle;
+    return brightness == .light ? SBBTheme.light(baseStyle: customizedBaseStyle) : SBBTheme.dark(baseStyle: customizedBaseStyle);
+  }
+
+  Future<SBBToastStyle> pumpAndResolveToastStyle(WidgetTester tester, ThemeData theme) async {
+    SBBToastStyle? toastStyle;
+    await tester.pumpWidget(
+      MaterialApp(
+        theme: theme,
+        home: Builder(
+          builder: (context) {
+            toastStyle = Theme.of(context).sbbToastTheme!.style!;
+            return const SizedBox.shrink();
+          },
+        ),
+      ),
+    );
+    return toastStyle!;
+  }
+
+  void expectToastFontPropertiesDeriveFromSBBTextTheme(SBBToastStyle toastStyle, SBBTextTheme textTheme) {
+    expect(toastStyle.titleTextStyle, isNotNull, reason: 'the default theme must provide a toast title text style');
+    expect(toastStyle.actionTextStyle, isNotNull, reason: 'the default theme must provide a toast action text style');
+    // The toast title uses the `smallLight` role and the toast action uses the `smallBold` role of the
+    // active SBB text theme. The font properties must come from the active text theme's roles.
+    // Only the non-color font properties are compared role by role because the toast may resolve
+    // the rendered text color separately.
+    final title = toastStyle.titleTextStyle!;
+    final expectedTitle = textTheme.smallLight!;
+    expect(title.fontFamily, expectedTitle.fontFamily, reason: 'toast title fontFamily must match SBBTextTheme smallLight');
+    expect(title.fontSize, expectedTitle.fontSize, reason: 'toast title fontSize must match SBBTextTheme smallLight');
+    expect(title.fontWeight, expectedTitle.fontWeight, reason: 'toast title fontWeight must match SBBTextTheme smallLight');
+    expect(title.height, expectedTitle.height, reason: 'toast title height must match SBBTextTheme smallLight');
+    final action = toastStyle.actionTextStyle!;
+    final expectedAction = textTheme.smallBold!;
+    expect(action.fontFamily, expectedAction.fontFamily, reason: 'toast action fontFamily must match SBBTextTheme smallBold');
+    expect(action.fontSize, expectedAction.fontSize, reason: 'toast action fontSize must match SBBTextTheme smallBold');
+    expect(action.fontWeight, expectedAction.fontWeight, reason: 'toast action fontWeight must match SBBTextTheme smallBold');
+    expect(action.height, expectedAction.height, reason: 'toast action height must match SBBTextTheme smallBold');
+  }
+
+  for (final brightness in [Brightness.light, Brightness.dark]) {
+    testWidgets('default toast theme derives its text styles from SBBTextTheme (${brightness.name})', (tester) async {
+      final theme = brightness == .light ? SBBTheme.light() : SBBTheme.dark();
+      final toastStyle = await pumpAndResolveToastStyle(tester, theme);
+
+      expectToastFontPropertiesDeriveFromSBBTextTheme(toastStyle, theme.sbbTextTheme);
+
+      // The toast text styles must not be plain re-declarations of the static, theme-independent
+      // SBBTextStyles constants: the active text-theme roles theme those constants (e.g. by
+      // applying the brightness dependent default text color), so equality with the raw constants
+      // does not hold.
+      expect(toastStyle.titleTextStyle, isNot(SBBTextStyles.smallLight));
+      expect(toastStyle.actionTextStyle, isNot(SBBTextStyles.smallBold));
+
+      // The roles of the light and dark default text themes carry different default text colors,
+      // so a brightness independent constant must not satisfy both variants.
+    });
+
+    testWidgets('default toast theme follows a customized SBBTextTheme (${brightness.name})', (tester) async {
+      const customizedTitle = TextStyle(fontFamily: 'Roboto', fontSize: 13.0, fontWeight: FontWeight.w300, height: 1.23);
+      const customizedAction = TextStyle(fontFamily: 'Roboto', fontSize: 11.0, fontWeight: FontWeight.w600, height: 1.4);
+      final theme = themeWithCustomizedTextTheme(
+        brightness: brightness,
+        smallLight: customizedTitle,
+        smallBold: customizedAction,
+      );
+
+      final toastStyle = await pumpAndResolveToastStyle(tester, theme);
+      expect(toastStyle.titleTextStyle, customizedTitle);
+      expect(toastStyle.actionTextStyle, customizedAction);
+      expect(toastStyle.titleTextStyle, isNot(SBBTheme.light().sbbTextTheme.smallLight));
+      expect(toastStyle.actionTextStyle, isNot(SBBTheme.dark().sbbTextTheme.smallBold));
+    });
+  }
+}

