+import 'dart:io';
+
+import 'package:skills/src/core/skill_scanner.dart';
+import 'package:skills/src/ide/adapters/agent_skills_adapter.dart';
+import 'package:skills/src/ide/ide.dart';
+import 'package:test/test.dart';
+import 'package:test_descriptor/test_descriptor.dart' as d;
+
+void main() {
+  group('Given the generic IDE', () {
+    test('when resolving the skills path then it is .agents/skills', () {
+      final path = Ide.generic.skillsPath('project');
+
+      expect(path, endsWith('.agents/skills'));
+      expect(path, isNot(contains('.agent/')));
+    });
+
+    test(
+        'when a directory marker exists then generic is detected for '
+        '.agents and not for the old .agent name', () async {
+      await d.dir('agents_project', [d.dir('.agents')]).create();
+      await d.dir('agent_project', [d.dir('.agent')]).create();
+
+      expect(Ide.generic.isDetected(d.path('agents_project')), isTrue);
+      expect(Ide.generic.isDetected(d.path('agent_project')), isFalse);
+    });
+
+    group('and an agent-skills adapter bound to the generic skills path', () {
+      test('when installing then the skill is written under .agents/skills',
+          () async {
+        await d.dir('pkg', [
+          d.dir('skills', [
+            d.dir('pkg-thing', [
+              d.file('SKILL.md',
+                  '---\nname: pkg-thing\ndescription: x\n---\nbody'),
+            ]),
+          ]),
+        ]).create();
+
+        final adapter =
+            AgentSkillsAdapter(Ide.generic.skillsPath(d.path('project')));
+
+        final name = await adapter.installSkill(
+          ScannedSkill(
+            packageName: 'pkg',
+            skillName: 'pkg-thing',
+            skillPath: d.path('pkg/skills/pkg-thing'),
+          ),
+        );
+
+        expect(name, equals('pkg-thing'));
+        expect(
+          Directory(d.path('project/.agents/skills/pkg-thing')).existsSync(),
+          isTrue,
+        );
+        expect(
+          Directory(d.path('project/.agent/skills/pkg-thing')).existsSync(),
+          isFalse,
+        );
+      });
+    });
+  });
+}
