+void loggableTest(
+  Object description,
+  dynamic Function() body, {
+  String? testOn,
+  Timeout? timeout,
+  Object? skip,
+  Object? tags,
+  Map<String, dynamic>? onPlatform,
+  int? retry,
+}) {
+  test(
+    description,
+    body,
+    testOn: testOn,
+    timeout: timeout,
+    skip: skip,
+    tags: tags,
+    onPlatform: onPlatform,
+    retry: retry,
+  );
+}
+
+/// Monotonic counter giving every log-marker message in this file a unique
+/// text so the status line the compact reporter flushes with it is never
+/// folded back into its previous occurrence.
+int _logMarkerSequence = 0;
