+              reason: 'dep2-skill1 was not selected and must not be installed',
+            );
+          }));
+
+      loggableTest(
+          'when running `skills get` for two IDEs (interactive) and the '
+          'user only keeps dep1-skill1 selected, then dep1-skill1 and only '
+          'dep1-skill1 should be installed for both IDEs',
+          guardedBody(
+              'when running `skills get` for two IDEs (interactive) and the user only keeps dep1-skill1 selected, then dep1-skill1 and only dep1-skill1 should be installed for both IDEs',
+              () async {
+            final dialog = NameSelectingDialogSupport(
+              keepOptions: {'dep1', 'dep1-skill1'},
+            );
+
+            // Both the generic (.agents) and cursor IDEs are auto-detected
+            // from the project markers, so no explicit --ide is passed.
+            await runGet(getAutoArgs(), dialog);
+
+            for (final ideDir in ['.agents', '.cursor']) {
+              expect(
+                await installedIn(ideDir, 'dep1-skill1'),
+                isTrue,
+                reason: 'the same selected skill must be installed for every '
+                    'targeted IDE',
+              );
+              expect(
+                await installedIn(ideDir, 'dep1-skill2'),
+                isFalse,
+                reason: 'a deselected skill must not be installed for any '
+                    'targeted IDE',
+              );
+              expect(
+                await installedIn(ideDir, 'dep2-skill1'),
+                isFalse,
+                reason: 'a deselected skill must not be installed for any '
+                    'targeted IDE',
+              );
+            }
+
+            final genericSkills = await manifestSkillNames(Ide.generic.cliName);
+            final cursorSkills = await manifestSkillNames(Ide.cursor.cliName);
+            expect(
+              genericSkills,
+              equals({'dep1-skill1'}),
+              reason: 'the manifest must record the selected skill for the '
+                  'generic IDE',
+            );
+            expect(
+              cursorSkills,
+              equals(genericSkills),
+              reason: 'the same selected set of skills must be recorded for '
+                  'every targeted IDE',
+            );
+          }));
+
+      loggableTest(
+          'when running `skills get` (interactive) and the user is '
+          'presented a selection, then confirming it unchanged installs '
+          'something',
+          guardedBody(
+              'when running `skills get` (interactive) and the user is presented a selection, then confirming it unchanged installs something',
+              () async {
+            // This test pins down that the interactive selection is genuinely
+            // presented: an implementation whose selection prompt can never be
+            // confirmed (for example a terminal-backed dialog that silently
+            // aborts when no terminal is attached, while the surrounding code
+            // swallows that abort) leaves the command installing nothing and
+            // is therefore reported here instead of silently skipping the
+            // behavioral tests above.
+            final dialog = NameSelectingDialogSupport();
+
+            await runGet(getAutoArgs(), dialog);
+
+            final installed = <String>{
+              for (final ideDir in ['.agents', '.cursor'])
+                for (final skill in [
+                  'dep1-skill1',
+                  'dep1-skill2',
+                  'dep2-skill1'
+                ])
+                  if (await installedIn(ideDir, skill)) '$ideDir/$skill',
+            };
+            expect(
+              installed,
+              isNotEmpty,
+              reason: 'confirming the presented selection unchanged must '
+                  'install at least one skill; the offered defaults never '
+                  'deselect every available skill',
+            );
+            // Whatever was installed must be a consistent selection: a skill
+            // that is installed for one targeted IDE but missing for another
+            // points at an aborted installation mid-way.
+            for (final skill in ['dep1-skill1', 'dep1-skill2', 'dep2-skill1']) {
+              if (await installedIn('.agents', skill)) {
+                expect(
+                  await installedIn('.cursor', skill),
+                  isTrue,
+                  reason: 'the same selected set of skills is installed for '
+                      'every targeted IDE',
+                );
+              }
+            }
+          }));
+
+      loggableTest(
+          'when running `skills get` (interactive) and the user cancels '
+          'the selection, then no skills should be installed',
+          guardedBody(
+              'when running `skills get` (interactive) and the user cancels the selection, then no skills should be installed',
+              () async {
+            // Cancelling any offered selection aborts the installation, like a
+            // user pressing escape in the dialog.
+            final dialog = CancellingDialogSupport();
+
+            await runGet(getArgs([Ide.generic.cliName]), dialog);
+
+            for (final skill in ['dep1-skill1', 'dep1-skill2', 'dep2-skill1']) {
+              expect(
+                await installedIn('.agents', skill),
+                isFalse,
+                reason: 'canceling the selection installs nothing',
+              );
+            }
+            // Nothing may have been recorded either: a false-positive cancel
+            // test that passes only because the IDE output directory was never
+            // populated would be caught here, since a recorded skill always
+            // implies an attempted installation.
+            expect(
+              await manifestSkillNames(Ide.generic.cliName),
+              isEmpty,
+              reason: 'canceling the selection may not record skills in the '
+                  'manifest',
+            );
+          }));
+
+      loggableTest(
+        'when running `skills get` (interactive) and the user confirms '
+        'with no skills selected, then no skills should be installed',
+        guardedBody(
+            'when running `skills get` (interactive) and the user confirms with no skills selected, then no skills should be installed',
+            () async {
+          // Confirming an empty selection installs nothing.
+          final dialog = EmptySelectionDialogSupport();
+
+          await runGet(getArgs([Ide.generic.cliName]), dialog);
+
+          for (final skill in ['dep1-skill1', 'dep1-skill2', 'dep2-skill1']) {
+            expect(
+              await installedIn('.agents', skill),
+              isFalse,
+              reason: 'confirming with nothing selected installs nothing',
+            );
+          }
+          expect(
+            await manifestSkillNames(Ide.generic.cliName),
+            isEmpty,
+            reason: 'an empty selection may not record skills in the '
+                'manifest',
+          );
+        }),
+      );
+    },
+  );
+}
