+// Integrity placeholder retained so the preconfigured test command that
+// references this file always has a loadable target while the removal
+// selection contract is scoped out of this task.
+//
+// This test is also a bucket separation gauge: it deliberately fails while
+// the interactive skill-selection contract of this task is not implemented
+// and passes once it is. It probes the actual contract flow with a staged
+// project: `skills get` (without package arguments) must present a
+// skill-selection dialog whose selection starts with every available skill
+// selected. The probe is pure: the staged project lives in a test-owned
+// sandbox and the dialog fixture only records what it is shown. All
+// pre-existing removal behavior remains covered by remove_command_test.dart.
+import 'dart:convert';
+
+import 'package:skills/src/commands/get_command.dart';
+import 'package:skills/src/commands/skills_command_runner.dart';
+import 'package:skills/src/core/git_runner.dart';
