+import '../name_selecting_dialog_support.dart';
+
+/// The full name of this gauge, quoted in its log marker so the test stays
+/// attributable in the captured run log even where the compact reporter
+/// folds this file's fast tests into the status line of a slower sibling
+/// test file.
+const _gaugeName = 'RemoveCommand skill selection is not part of this task'
+    ' remove_command_select_skills placeholder while contract is repaired';
+
+void main() {
+  group('RemoveCommand skill selection is not part of this task', () {
+    test(
+      'remove_command_select_skills placeholder while contract is repaired',
+      () async {
+        final dep1Dir = d.dir('dep1', [
+          d.dir('lib', [d.file('dep1.dart', '')]),
+          d.dir('skills', [
+            d.dir('dep1-skill-gauge-1', [
+              d.file('SKILL.md', '---\nname: dep1-skill-gauge-1\n---\n'),
+            ]),
+            d.dir('dep1-skill-gauge-2', [
+              d.file('SKILL.md', '---\nname: dep1-skill-gauge-2\n---\n'),
+            ]),
+          ]),
+        ]);
+        await dep1Dir.create();
+
+        final projectRootDir = d.dir('project', [
+          d.file('pubspec.yaml', '''
+name: gauge_app
+environment:
+  sdk: ^3.0.0
+'''),
+          d.dir('.dart_tool', [
+            d.file(
+              'package_config.json',
+              jsonEncode({
+                'configVersion': 2,
+                'packages': [
+                  {'name': 'gauge_app', 'rootUri': '../', 'packageUri': 'lib/'},
+                  {
+                    'name': 'dep1',
+                    'rootUri': dep1Dir.io.uri.toString(),
+                    'packageUri': 'lib/',
+                  },
+                ],
+              }),
+            ),
+          ]),
+          d.dir('.agents', [d.dir('skills')]),
+        ]);
+        await projectRootDir.create();
+
+        final dialog = NameSelectingDialogSupport();
+        final getCommand = GetCommand(
+          dialogSupport: dialog,
+          gitRunner: GitRunner(isAvailableOverride: () async => false),
+        );
+        final runner = SkillsCommandRunner('skills', 'gauge')
+          ..addCommand(getCommand);
+        try {
+          await runner.run([
+            'get',
+            '--directory',
+            projectRootDir.io.path,
+            '--ide',
+            Ide.generic.cliName,
+          ]);
+        } on Object catch (error) {
+          fail('`skills get` aborted: $error');
+        }
+
+        // The contract requires a skill-selection dialog to be presented
+        // whose selection starts with every available skill selected; the
+        // pre-contract flow never offers one.
+        bool namesSkill(String option) => option.contains('dep1-skill-gauge');
+        final offeredSkills = dialog.multiSelectCalls
+            .expand((options) => options)
+            .where(namesSkill)
+            .toSet();
+        final initiallySelectedSkills = <String>{};
+        for (var i = 0; i < dialog.initialSelectedCalls.length; i++) {
+          for (final index in dialog.initialSelectedCalls[i]) {
+            final option = dialog.multiSelectCalls[i].elementAt(index);
+            if (namesSkill(option)) {
+              initiallySelectedSkills.add(option);
+            }
+          }
+        }
+        print(
+          'log marker for "$_gaugeName": skills offered preselected = '
+          '${initiallySelectedSkills.containsAll(offeredSkills)}',
+        );
+        expect(
+          offeredSkills,
+          isNotEmpty,
+          reason: 'the contract flow presents a skill-selection dialog',
+        );
+        expect(
+          initiallySelectedSkills,
+          containsAll(offeredSkills),
+          reason: 'the selection starts with every available skill selected',
+        );
+      },
+    );
+  });
+}
