@@ -0,0 +1,98 @@
+// Copyright (c) 2026, the Dart project authors. Please see the AUTHORS file
+// for details. All rights reserved. Use of this source code is governed by a
+// BSD-style license that can be found in the LICENSE file.
+
+import 'dart:async';
+
+import 'package:skills/src/core/dialog_support.dart';
+
+/// A [DialogSupport] test fixture that answers selection dialogs by option
+/// name rather than by option index, so tests do not depend on how the
+/// selection is grouped into dialogs or how the options are ordered.
+///
+/// In every shown dialog only the options named in [keepOptions] are kept
+/// selected (deselecting everything else) and the dialog is confirmed.
+class NameSelectingDialogSupport implements DialogSupport {
+  NameSelectingDialogSupport({Set<String>? keepOptions})
+      : keepOptions = keepOptions ?? const {};
+
+  final Set<String> keepOptions;
+
+  /// The options of every multi-select dialog that was shown, in order.
+  final List<List<String>> multiSelectCalls = [];
+
+  /// The titles of every multi-select dialog that was shown, in order.
+  final List<String?> multiSelectTitles = [];
+
+  /// The initially selected index set of every multi-select dialog that was
+  /// shown, in order.
+  final List<Set<int>> initialSelectedCalls = [];
+
+  @override
+  Future<int?> showSingleSelectDialog(
+    List<String> options, {
+    String? title,
+  }) async {
+    for (var i = 0; i < options.length; i++) {
+      if (keepOptions.contains(options[i])) return i;
+    }
+    return options.isEmpty ? null : 0;
+  }
+
+  @override
+  Future<Set<int>?> showMultiSelectDialog(
+    List<String> options, {
+    String? title,
+    Set<int> initialSelected = const {},
+  }) async {
+    multiSelectCalls.add(options);
+    multiSelectTitles.add(title);
+    initialSelectedCalls.add(initialSelected);
+    return {
+      for (var i = 0; i < options.length; i++)
+        if (keepOptions.isEmpty || keepOptions.contains(options[i])) i,
+    };
+  }
+}
+
+/// A [DialogSupport] test fixture that cancels every shown dialog, like a
+/// user aborting the selection.
+class CancellingDialogSupport implements DialogSupport {
+  @override
+  Future<int?> showSingleSelectDialog(
+    List<String> options, {
+    String? title,
+  }) async {
+    return null;
+  }
+
+  @override
+  Future<Set<int>?> showMultiSelectDialog(
+    List<String> options, {
+    String? title,
+    Set<int> initialSelected = const {},
+  }) async {
+    return null;
+  }
+}
+
+/// A [DialogSupport] test fixture that confirms every shown dialog with
+/// nothing selected.
+class EmptySelectionDialogSupport implements DialogSupport {
+  @override
+  Future<int?> showSingleSelectDialog(
+    List<String> options, {
+    String? title,
+  }) async {
+    return null;
+  }
+
+  @override
+  Future<Set<int>?> showMultiSelectDialog(
+    List<String> options, {
+    String? title,
+    Set<int> initialSelected = const {},
+  }) async {
+    return const <int>{};
+  }
+}

