diff --git a/test/utils.dart b/test/utils.dart
new file mode 100644
index 0000000..3e892c9
--- /dev/null
+++ b/test/utils.dart
@@ -0,0 +1,87 @@
+import 'dart:convert';
+import 'dart:io';
+
+import 'package:path/path.dart' as p;
+import 'package:test_descriptor/test_descriptor.dart' as d;
+
+class Dependency {
+  final String name;
+  final String? path;
+  const Dependency(this.name, {this.path});
+}
+
+d.FileDescriptor pubspec(
+  String name, {
+  String version = '1.0.0',
+  List<Dependency> dependencies = const [],
+  List<Dependency> devDependencies = const [],
+  List<String>? workspace,
+  String? resolution,
+  String? publishTo,
+  String? extra, // For melos blocks or other raw YAML
+}) {
+  final buffer = StringBuffer('''
+name: $name
+environment:
+  sdk: ^3.10.0
+version: $version
+''');
+  if (publishTo != null) {
+    buffer.writeln('publish_to: $publishTo');
+  }
+  if (resolution != null) {
+    buffer.writeln('resolution: $resolution');
+  }
+  if (workspace != null && workspace.isNotEmpty) {
+    buffer.writeln('workspace:');
+    for (final member in workspace) {
+      buffer.writeln('  - $member');
+    }
+  }
+  if (extra != null) {
+    buffer.writeln(extra);
+  }
+  if (dependencies.isNotEmpty) {
+    buffer.writeln('dependencies:');
+    for (final dependency in dependencies) {
+      final path = dependency.path ?? '../${dependency.name}';
+      buffer.writeln('''
+  ${dependency.name}:
+    path: $path
+''');
+    }
+  }
+  if (devDependencies.isNotEmpty) {
+    buffer.writeln('dev_dependencies:');
+    for (final dependency in devDependencies) {
+      final path = dependency.path ?? '../${dependency.name}';
+      buffer.writeln('''
+  ${dependency.name}:
+    path: $path
+''');
+    }
+  }
+  return d.file('pubspec.yaml', buffer.toString());
+}
+
+/// Appends a resolved-but-undeclared package entry to an existing
+/// package_config.json, simulating a package that ended up in the package
+/// config without being declared in any pubspec.
+Future<void> appendPackageConfigEntry(
+  String configPath,
+  String packageName,
+  String packageRootPath,
+) async {
+  final configFile = File(configPath);
+  final config =
+      jsonDecode(await configFile.readAsString()) as Map<String, Object?>;
+  final packages = (config['packages'] as List).cast<Map<String, Object?>>();
+  packages.add(<String, Object?>{
+    'name': packageName,
+    'rootUri': p.toUri(packageRootPath).toString(),
+    'packageUri': 'lib/',
+  });
+  await configFile.writeAsString(
+    const JsonEncoder.withIndent('  ').convert(config),
+  );
+}

