#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <stdlib.h>
int main(int argc, char **argv) {
    const char *self = strrchr(argv[0], '/');
    self = self ? self + 1 : argv[0];
    int is_cxx = strstr(self, "++") != NULL;
    const char *real = is_cxx ? "/usr/bin/clang++-17" : "/usr/bin/clang-17";
    char **out = malloc(sizeof(char *) * (argc + 2));
    int j = 0;
    out[j++] = (char *)real;
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-index-store-path") == 0) { i++; continue; }
        out[j++] = argv[i];
    }
    out[j] = NULL;
    execv(real, out);
    perror("execv");
    return 127;
}
WRAP
cc -O2 -o /tmp/ccwrap/clang /tmp/ccwrap/clangwrap.c && cp /tmp/ccwrap/clang /tmp/ccwrap/clang++

