test_patch:
diff --git a/core/src/test/java/eu/rekawek/coffeegb/core/joypad/SgbFourPlayerInputTest.java b/core/src/test/java/eu/rekawek/coffeegb/core/joypad/SgbFourPlayerInputTest.java
