index 00000000..09110b25
--- /dev/null
+++ b/core/src/test/java/eu/rekawek/coffeegb/core/joypad/SgbFourPlayerInputTest.java
@@ -0,0 +1,477 @@
+package eu.rekawek.coffeegb.core.joypad;
+
+import eu.rekawek.coffeegb.core.cpu.InterruptManager;
+import eu.rekawek.coffeegb.core.events.EventBus;
+import eu.rekawek.coffeegb.core.events.EventBusImpl;
+import eu.rekawek.coffeegb.core.state.ComponentState;
+import eu.rekawek.coffeegb.core.sgb.SuperGameboy;
+import org.junit.Before;
+import org.junit.Test;
+
+import java.lang.reflect.Constructor;
+import java.lang.reflect.Method;
+import java.lang.reflect.Modifier;
+import java.lang.reflect.Proxy;
+import java.util.Collection;
+import java.util.List;
+import java.util.Set;
+
+import static org.junit.Assert.assertEquals;
+import static org.junit.Assert.assertNotNull;
+import static org.junit.Assert.assertTrue;
+import static org.junit.Assert.fail;
+
+/**
+ * Four-slot host-input phase. It compiles against only classes that already exist on the
+ * base revision and fails with a plain explanation while the seam classes are absent, so
+ * the test rejects a missing seam without constraining the seam representation beyond the
+ * public contract. The single validated check walks every observable obligation of the
+ * phase through the public seam and the public JOYP register: independent slots with
+ * wraparound, one/two/four-player transitions, released and live slots, per-slot direction
+ * rows, the next-controller feedback path that reports the current multiplayer mode and
+ * selected controller as line readings, the legacy constructor fallback, the legacy
+ * press/release interaction, live source sampling across capture/restore (including the
+ * preserved JOYP selector level), snapshot validation and immutability, the fully released
+ * reads after a source becomes fully released, and malformed framing recovery.
+ */
+public class SgbFourPlayerInputTest {
+
+    private static final int JOYP = 0xff00;
+    /** Selector level that floats both rows high; reads the next-controller feedback path. */
+    private static final int BOTH_ROWS = 0x30;
+    /** Selector that pulls the button row (A/B/SELECT/START) low. */
+    private static final int BUTTON_ROW = 0x10;
+    /** Selector that pulls the direction row (RIGHT/LEFT/UP/DOWN) low. */
+    private static final int DIRECTION_ROW = 0x20;
+
+    private EventBusImpl sgbBus;
+    private InterruptManager interrupts;
+    private Joypad joypad;
+    private FourSlotSource source;
+
+    /**
+     * Returns the four-slot seam helper bound to this fixture, or null while the public seam
+     * class file is absent from the tested revision. Instantiation is deferred to the test so
+     * this suite still loads on the base revision before the seam exists.
+     */
+    private FourSlotSource findSeam() {
+        try {
+            return new FourSlotSource();
+        } catch (IllegalStateException | NoClassDefFoundError absent) {
+            return null;
+        }
+    }
+
+    @Before
+    public void setUp() {
+        sgbBus = new EventBusImpl(null, null, false);
+        new SuperGameboy(sgbBus);
+        interrupts = new InterruptManager(false);
+        source = findSeam();
+        if (source != null) {
+            joypad = source.newJoypad(interrupts, sgbBus);
+        }
+    }
+
+    @Test
+    public void fourDistinctPlayersRotateWithExactIdFeedbackAndWrap() {
+        requireSeam();
+        requireSnapshotContractHolds();
+        assertLegacyConstructorReadsReleased();
+
+        // --- four distinct players rotate with exact controller feedback and wrap ------------
+        source.hold(0, Set.of(Button.A));
+        source.hold(1, Set.of(Button.B));
+        source.hold(2, Set.of(Button.SELECT));
+        source.hold(3, Set.of(Button.START));
+        selectMode(3);
+
+        int[] expectedButtons = {0x0e, 0x0d, 0x0b, 0x07};
+        for (int player = 0; player < 4; player++) {
+            writeSelector(BOTH_ROWS);
+            assertEquals("next-controller feedback reaches selected controller " + (player + 1),
+                    0x0f - player, lines());
+            writeSelector(BUTTON_ROW);
+            assertEquals("selected controller " + (player + 1), expectedButtons[player], lines());
+            advanceSelection();
+        }
+        writeSelector(BOTH_ROWS);
+        assertEquals("feedback wraps to controller one", 0x0f, lines());
+        writeSelector(BUTTON_ROW);
+        assertEquals("selection wraps to controller one", 0x0e, lines());
+
+        // --- each slot reports its own direction row -----------------------------------------
+        source.hold(0, Set.of(Button.UP));
+        source.hold(1, Set.of(Button.LEFT));
+        source.hold(2, Set.of(Button.RIGHT));
+        source.hold(3, Set.of(Button.DOWN));
+        selectMode(3);
+        int[] expectedDirections = {0x0b, 0x0d, 0x0e, 0x07};
+        for (int player = 0; player < 4; player++) {
+            writeSelector(DIRECTION_ROW);
+            assertEquals("direction row for controller " + (player + 1),
+                    expectedDirections[player], lines());
+            advanceSelection();
+        }
+        writeSelector(DIRECTION_ROW);
+        assertEquals("direction row wraps to controller one", 0x0b, lines());
+
+        // --- released and unassigned slots read fully released -------------------------------
+        source.releaseAll();
+        selectMode(3);
+        advanceSelection(); // controller two, with nothing held
+        writeSelector(BUTTON_ROW);
+        assertEquals("an unassigned controller reads released", 0x0f, lines());
+        writeSelector(DIRECTION_ROW);
+        assertEquals("an unassigned controller reads released on the direction row", 0x0f, lines());
+
+        // --- the source is sampled at the Joypad clock boundary ------------------------------
+        // Host-side holds and releases enter before a mode change; the mode request packet
+        // itself advances the Joypad clock, latching that sample. The checks below therefore
+        // only change the source while the selector level and the selected controller stay
+        // put, so a host change cannot be masked by a same-tick JOYP write.
+        selectMode(3);
+        advanceSelection(); // controller two
+        writeSelector(BUTTON_ROW);
+        source.hold(1, Set.of(Button.A));
+        assertEquals("host input appears at the next clock boundary", 0x0e, tickedLines());
+        source.hold(1, Set.of());
+        assertEquals("a released host change appears at the next clock boundary",
+                0x0f, tickedLines());
+        assertEquals("a repeated released sample keeps controller two released at the clock",
+                0x0f, tickedLines());
+
+        // --- the legacy press/release event stream stays P1-only ------------------------------
+        source.releaseAll();
+        selectMode(3); // controller one, with the source latched as released
+        joypad.init(sgbBus);
+        sgbBus.post(new ButtonPressEvent(Button.A));
+        writeSelector(BUTTON_ROW);
+        assertEquals("controller one combines the legacy event stream with the source",
+                0x0e, lines());
+        advanceSelection();
+        writeSelector(BUTTON_ROW);
+        assertEquals("a legacy P1 event must not leak into controller two", 0x0f, lines());
+        sgbBus.post(new ButtonReleaseEvent(Button.A));
+        advanceSelection(); // controller three
+        writeSelector(BUTTON_ROW);
+        assertEquals("an unrelated controller is unaffected by legacy events", 0x0f, lines());
+        advanceSelection(); // controller four
+        advanceSelection(); // wraps back to controller one
+        writeSelector(BUTTON_ROW);
+        assertEquals("releasing the P1 legacy event returns controller one to released",
+                0x0f, lines());
+
+        // --- one- and two-player modes keep slots independent across transitions -------------
+        source.hold(0, Set.of(Button.A));
+        source.hold(1, Set.of(Button.B));
+        source.hold(2, Set.of(Button.SELECT));
+        // The multiplayer mode request advances the clock, so these holds are latched
+        // before the mode change is sampled.
+        selectMode(1);
+        writeSelector(BOTH_ROWS);
+        assertEquals("two-player mode selects controller one", 0x0f, lines());
+        writeSelector(BUTTON_ROW);
+        assertEquals("two-player controller one", 0x0e, lines());
+        advanceSelection();
+        writeSelector(BUTTON_ROW);
+        assertEquals("two-player controller two", 0x0d, lines());
+        selectMode(0);
+        writeSelector(BOTH_ROWS);
+        assertEquals("one-player mode reports only controller one", 0x0f, lines());
+        writeSelector(BUTTON_ROW);
+        assertEquals("one-player mode returns to controller one", 0x0e, lines());
+        selectMode(3);
+        advanceSelection();
+        advanceSelection();
+        writeSelector(BUTTON_ROW);
+        assertEquals("four-player mode selects controller three", 0x0b, lines());
+        selectMode(0);
+        writeSelector(BUTTON_ROW);
+        assertEquals("returning to one player cannot retain another controller", 0x0e, lines());
+
+        // --- capture/restore resumes the multiplexing state and reads live input -------------
+        selectMode(3);
+        advanceSelection(); // controller two, holding Button.B
+        writeSelector(BOTH_ROWS);
+        assertEquals("controller two selected before capture", 0x0e, lines());
+        ComponentState<Joypad> state = joypad.captureState();
+        selectMode(0); // return to one-player mode
+        writeSelector(BUTTON_ROW);
+        assertEquals("one-player mode reads controller one", 0x0e, lines());
+        joypad.restoreState(state);
+        assertEquals("restore preserves the captured JOYP selector level", BOTH_ROWS,
+                joypad.getByte(JOYP) & 0x30);
+        writeSelector(BOTH_ROWS);
+        assertEquals("restored controller two reports its feedback", 0x0e, lines());
+        writeSelector(BUTTON_ROW);
+        assertEquals("restored selected controller two", 0x0d, lines());
+        advanceSelection();
+        writeSelector(BUTTON_ROW);
+        assertEquals("restore retains the multiplexing sequence", 0x0b, lines());
+
+        // --- live host changes after restore keep applying at clock boundaries ---------------
+        source.hold(2, Set.of(Button.START));
+        writeSelector(BUTTON_ROW);
+        assertEquals("restored controller three reads the live source after a clock boundary",
+                0x07, tickedLines());
+
+        // --- a fully released source is observed at the next clock boundary -----------------
+        // Whatever slot is selected must read released after the host source reports no
+        // buttons, with no stuck button retained by the Joypad.
+        source.hold(0, Set.of());
+        source.hold(1, Set.of());
+        source.hold(2, Set.of(Button.SELECT));
+        source.hold(3, Set.of());
+        selectMode(3);
+        advanceSelection();
+        advanceSelection(); // controller three, holding Button.SELECT
+        writeSelector(BUTTON_ROW);
+        assertEquals("controller three holds its button before the source is released",
+                0x0b, tickedLines());
+        source.releaseAll();
+        assertEquals("after the source is released controller three reads released at the "
+                + "next clock boundary", 0x0f, tickedLines());
+        advanceSelection(); // controller four
+        writeSelector(BUTTON_ROW);
+        assertEquals("controller four stays released at the clock", 0x0f, tickedLines());
+        advanceSelection(); // wraps to controller one
+        writeSelector(BUTTON_ROW);
+        assertEquals("controller one stays released at the clock", 0x0f, tickedLines());
+
+        // --- malformed pulse framing cannot block a later valid command ----------------------
+        writeSelector(BOTH_ROWS);
+        writeSelector(0x00);
+        for (int i = 0; i < 19; i++) {
+            writeSelector((i & 1) == 0 ? 0x20 : 0x10);
+        }
+        source.releaseAll();
+        source.hold(0, Set.of(Button.A));
+        source.hold(1, Set.of(Button.B));
+        selectMode(1);
+        writeSelector(BUTTON_ROW);
+        assertEquals("a valid command after malformed framing selects controller one",
+                0x0e, lines());
+        advanceSelection();
+        writeSelector(BUTTON_ROW);
+        assertEquals("later framing still selects controller two", 0x0d, lines());
+    }
+
+    // --- seam-boundary assertions -----------------------------------------------------------
+
+    private void requireSeam() {
+        assertTrue("The independent 1-4 player phase must expose the public four-slot input seam: "
+                + "an interface PlayerInputSource with exactly one abstract no-argument method, "
+                + "a snapshot type PlayerInputSnapshot with the public static no-argument "
+                + "method released() and the public static of factory, and a Joypad constructor "
+                + "accepting the source.",
+                source != null);
+    }
+
+    private void assertLegacyConstructorReadsReleased() {
+        Joypad legacy = new Joypad(new InterruptManager(false), sgbBus, true);
+        legacy.setByte(JOYP, BUTTON_ROW);
+        assertEquals(
+                "the legacy three-argument constructor reads a fully released controller one",
+                0x0f, legacy.getByte(JOYP) & 0x0f);
+    }
+
+    /** Asserts released, deep immutability, and exactly-four public snapshot construction. */
+    private void requireSnapshotContractHolds() {
+        assertNotNull("PlayerInputSnapshot.released must produce a complete released sample",
+                source.releasedSnapshot());
+        source.useSnapshot(source.releasedSnapshot());
+        selectMode(0);
+        writeSelector(BUTTON_ROW);
+        assertEquals("the released snapshot reads all slots as released", 0x0f, lines());
+        source.useLiveSlots();
+        Set<Button> mutable = new java.util.HashSet<>(Set.of(Button.A));
+        source.useSnapshot(source.newSnapshot(List.of(mutable, Set.of(), Set.of(), Set.of())));
+        mutable.clear();
+        selectMode(0);
+        writeSelector(BUTTON_ROW);
+        assertEquals("snapshot must retain buttons after caller mutation", 0x0e, lines());
+        source.useLiveSlots();
+        try {
+            source.newSnapshot(List.of(Set.of(), Set.of(), Set.of()));
+            fail("PlayerInputSnapshot.of must reject fewer than four player slots");
+        } catch (IllegalArgumentException expected) {
+            // expected: exactly four slots are required
+        }
+        try {
+            source.newSnapshot(List.of(Set.of(), Set.of(), Set.of(), Set.of(), Set.of()));
+            fail("PlayerInputSnapshot.of must reject more than four player slots");
+        } catch (IllegalArgumentException expected) {
+            // expected: exactly four slots are required
+        }
+    }
+
+    // --- JOYP and SGB helpers ---------------------------------------------------------------
+
+    private int lines() {
+        return joypad.getByte(JOYP) & 0x0f;
+    }
+
+    /** Advances the Joypad clock once so a fresh source sample is latched, then reads JOYP. */
+    private int tickedLines() {
+        joypad.tick();
+        return lines();
+    }
+
+    private void advanceSelection() {
+        writeSelector(BUTTON_ROW);
+        writeSelector(BOTH_ROWS);
+    }
+
+    /** Selects a multiplayer mode: force controller one, then request {@code control} players. */
+    private void selectMode(int control) {
+        sendMultiplayerControl(0);
+        sendMultiplayerControl(control);
+        joypad.tick();
+    }
+
+    private void sendMultiplayerControl(int control) {
+        int[] packet = new int[16];
+        packet[0] = (0x11 << 3) | 1;
+        packet[1] = control & 0xff;
+        writeSelector(BOTH_ROWS);
+        writeSelector(0x00);
+        writeSelector(BOTH_ROWS);
+        for (int bitIndex = 0; bitIndex < packet.length * 8; bitIndex++) {
+            int bit = packet[bitIndex / 8] >> (bitIndex & 7) & 1;
+            writeSelector(bit == 0 ? 0x20 : 0x10);
+            writeSelector(BOTH_ROWS);
+        }
+
+        writeSelector(0x20);
+        writeSelector(BOTH_ROWS);
+    }
+
+    private void writeSelector(int selector) {
+        joypad.setByte(JOYP, selector);
+    }
+
+    /**
+     * A host-side stand-in for the documented public seam. It binds to the seam reflectively
+     * so this suite still loads while the seam classes are absent, and it checks only the
+     * public API shapes the contract names.
+     */
+    private final class FourSlotSource {
+        private final Class<?> sourceType;
+        private final Constructor<Joypad> seamConstructor;
+        private final Method releasedMethod;
+        private final Method snapshotFactory;
+        private final Object sourceProxy;
+        @SuppressWarnings("unchecked")
+        private final Set<Button>[] slots = new Set[]{Set.of(), Set.of(), Set.of(), Set.of()};
+        private Object fixedSnapshot;
+
+        /**
+         * Resolves the documented seam members by name, then validates every public shape the
+         * contract names: the interface with exactly one abstract no-argument method, the
+         * public static no-argument released() method, the public static of factory, and the
+         * Joypad constructor accepting the source.
+         */
+        private FourSlotSource() {
+            try {
+                sourceType = Class.forName("eu.rekawek.coffeegb.core.joypad.PlayerInputSource");
+                Class<?> snapshotType =
+                        Class.forName("eu.rekawek.coffeegb.core.joypad.PlayerInputSnapshot");
+                if (!sourceType.isInterface()) {
+                    throw new AssertionError(
+                            "PlayerInputSource must be a Java interface, found: " + sourceType);
+                }
+                Method[] abstractMethods = java.util.Arrays.stream(sourceType.getMethods())
+                        .filter(method -> Modifier.isAbstract(method.getModifiers()))
+                        .toArray(Method[]::new);
+                if (abstractMethods.length != 1 || abstractMethods[0].getParameterCount() != 0
+                        || !snapshotType.isAssignableFrom(abstractMethods[0].getReturnType())) {
+                    throw new AssertionError("PlayerInputSource must expose exactly one abstract "
+                            + "no-argument method returning a PlayerInputSnapshot, found: "
+                            + java.util.Arrays.toString(sourceType.getMethods()));
+                }
+                releasedMethod = snapshotType.getMethod("released");
+                if (!Modifier.isStatic(releasedMethod.getModifiers())
+                        || !snapshotType.isAssignableFrom(releasedMethod.getReturnType())) {
+                    throw new AssertionError("PlayerInputSnapshot must expose the public static "
+                            + "no-argument method released()");
+                }
+                snapshotFactory = snapshotType.getMethod("of", List.class);
+                if (!Modifier.isStatic(snapshotFactory.getModifiers())) {
+                    throw new AssertionError(
+                            "PlayerInputSnapshot.of must be a static factory accepting a List");
+                }
+                seamConstructor = Joypad.class.getConstructor(
+                        InterruptManager.class, EventBus.class, boolean.class, sourceType);
+                sourceProxy = Proxy.newProxyInstance(sourceType.getClassLoader(),
+                        new Class<?>[]{sourceType},
+                        (proxy, method, args) -> currentSnapshot());
+            } catch (ClassNotFoundException absent) {
+                throw new IllegalStateException(absent);
+            } catch (NoSuchMethodException absent) {
+                throw new IllegalStateException(
+                        "The seam must expose the documented released()/of members and the "
+                                + "Joypad constructor accepting the source", absent);
+            }
+        }
+
+        Joypad newJoypad(InterruptManager interruptManager, EventBus bus) {
+            try {
+                return seamConstructor.newInstance(interruptManager, bus, true, sourceProxy);
+            } catch (ReflectiveOperationException failure) {
+                throw new IllegalStateException(
+                        "Joypad must accept the injected four-slot source", failure);
+            }
+        }
+
+        void hold(int player, Set<Button> buttons) {
+            slots[player] = Set.copyOf(buttons);
+        }
+
+        void releaseAll() {
+            for (int player = 0; player < slots.length; player++) {
+                slots[player] = Set.of();
+            }
+        }
+
+        void useSnapshot(Object snapshot) {
+            fixedSnapshot = snapshot;
+        }
+
+        void useLiveSlots() {
+            fixedSnapshot = null;
+        }
+
+        Object releasedSnapshot() {
+            return invokeStatic(releasedMethod);
+        }
+
+        Object newSnapshot(List<? extends Collection<Button>> slotButtons) {
+            try {
+                return snapshotFactory.invoke(null, List.copyOf(slotButtons));
+            } catch (ReflectiveOperationException failure) {
+                Throwable cause = failure.getCause();
+                if (cause instanceof IllegalArgumentException rejection) {
+                    throw rejection;
+                }
+                throw new IllegalStateException(
+                        "PlayerInputSnapshot.of must build a snapshot from four slots", failure);
+            }
+        }
+
+        private Object invokeStatic(Method staticMethod) {
+            try {
+                return staticMethod.invoke(null);
+            } catch (ReflectiveOperationException failure) {
+                throw new IllegalStateException(
+                        "PlayerInputSnapshot." + staticMethod.getName()
+                                + " must be callable without arguments", failure);
+            }
+        }
+
+        private Object currentSnapshot() {
+            return fixedSnapshot != null ? fixedSnapshot
+                    : newSnapshot(List.of(slots[0], slots[1], slots[2], slots[3]));
+        }
+    }
+}

