 ];

+Matcher _isFlutter344ReleaseLine(VersionRange releaseLine) =>
+    predicate<String>((version) {
+      try {
+        return releaseLine.allows(Version.parse(version));
+      } on FormatException {
+        return version == '3.44.x';
+      }
+    }, 'is a Flutter 3.44 release-line version');
+
 void main() {
   group('packages get', () {
+    test('supports Dart 3.12', () {
+      final target = Version(3, 12, 0);
+      final expectedMinSdk = Version(3, 12, 0);
+      final dartWorkflows = {
+        '.github/workflows/bump_templates.yaml',
+        '.github/workflows/pub_publish.yaml',
+        '.github/workflows/spdx_license.yaml',
+      };
+      final sdkVersionPattern = RegExp(
+        'sdk\\s*:\\s*["' +
+            "'" +
+            '"]?' +
+            r'(\d+\.\d+\.\d+(?:-[^\s"' +
+            "'" +
+            '"]*)?)',
+      );
+      final flutterWorkflows = {
+        '.github/workflows/spdx_license_bot.yaml',
+        '.github/workflows/very_good_cli.yaml',
+      };
+      final flutterVersionPattern = RegExp(
+        'flutter-version\\s*:\\s*["' + "'" + '"]?' + r'([^\s"' + "'" + '"]+)',
+      );
+      final flutterReleaseLine = VersionRange(
+        min: Version(3, 44, 0),
+        max: Version(3, 45, 0),
+        includeMin: true,
+      );
+
+      String rawSdkConstraintOf(String pubspecPath) {
+        final file = File(pubspecPath);
