+          file.existsSync(),
+          isTrue,
+          reason: 'Expected to find $pubspecPath in the project.',
+        );
+        final document = loadYaml(file.readAsStringSync());
+        expect(
+          document,
+          isA<YamlMap>(),
+          reason: 'Expected $pubspecPath to contain a valid YAML mapping.',
+        );
+        final environment = (document as YamlMap)['environment'];
+        expect(
+          environment,
+          isA<YamlMap>(),
+          reason: 'Expected $pubspecPath to declare an environment section.',
+        );
+        final sdk = (environment as YamlMap)['sdk'];
+        expect(
+          sdk,
+          isA<String>(),
+          reason:
+              'Expected $pubspecPath to declare a Dart SDK constraint in '
+              'its environment section.',
+        );
+        return sdk as String;
+      }
+
+      List<String> versionsMatching(RegExp pattern, String content) => pattern
+          .allMatches(content)
+          .where(
+            (match) => !content
+                .substring(
+                  content.lastIndexOf('\n', match.start) + 1,
+                  match.start,
+                )
+                .contains('#'),
+          )
+          .map((match) => match.group(1)!)
+          .toList();
+
+      final pubspecFiles = [
+        'pubspec.yaml',
+        'tool/spdx_license/pubspec.yaml',
+        'tool/spdx_license/hooks/pubspec.yaml',
+      ];
+      for (final pubspecPath in pubspecFiles) {
+        final rawConstraint = rawSdkConstraintOf(pubspecPath);
+        final VersionConstraint constraint;
+        try {
+          constraint = VersionConstraint.parse(rawConstraint);
+        } on FormatException {
+          fail(
+            'Expected $pubspecPath to declare a valid Dart SDK version '
+            'constraint, but found "$rawConstraint".',
+          );
+        }
+        expect(
+          constraint.allows(target),
+          isTrue,
+          reason:
+              'Expected the Dart SDK constraint "$constraint" in '
+              '$pubspecPath to support Dart $target.',
+        );
+        expect(
+          constraint,
+          isA<VersionRange>(),
+          reason:
+              'Expected the Dart SDK constraint "$constraint" in '
+              '$pubspecPath to declare an explicit version range with a '
+              'minimum Dart SDK version.',
+        );
+        final min = (constraint as VersionRange).min;
+        expect(
+          min,
+          isNotNull,
+          reason:
+              'Expected the Dart SDK constraint "$constraint" in '
+              '$pubspecPath to declare an explicit minimum Dart SDK '
+              'version.',
+        );
+        expect(
+          min!.major == 3 && min.compareTo(expectedMinSdk) >= 0,
+          isTrue,
+          reason:
+              'Expected the minimum Dart SDK version declared in '
+              '$pubspecPath to be $expectedMinSdk or later within the '
+              'Dart 3 line, but found "$constraint".',
+        );
+        expect(
+          constraint.allows(Version(4, 0, 0)),
+          isFalse,
+          reason:
+              'Expected the Dart SDK constraint "$constraint" in '
+              '$pubspecPath to remain bounded to the Dart 3 line and '
+              'not admit Dart 4.0.0 or later.',
+        );
+      }
+
+      for (final workflowPath in dartWorkflows) {
+        final file = File(workflowPath);
+        expect(
+          file.existsSync(),
+          isTrue,
+          reason: 'Expected to find $workflowPath in the project.',
+        );
+        final content = file.readAsStringSync();
+        final versions = versionsMatching(sdkVersionPattern, content);
+        expect(
+          versions,
+          isNotEmpty,
+          reason:
+              'Expected $workflowPath to declare at least one Dart SDK '
+              'toolchain entry.',
+        );
+        for (final version in versions) {
+          final parsed = Version.parse(version);
+          expect(
+            parsed.major == 3 && parsed.compareTo(target) >= 0,
+            isTrue,
+            reason:
+                'Expected every Dart SDK toolchain declared in '
+                '$workflowPath to be $target or later within the Dart 3 '
+                'line, but found "$version".',
+          );
+        }
+      }
+
+      for (final workflowPath in flutterWorkflows) {
+        final file = File(workflowPath);
+        expect(
+          file.existsSync(),
+          isTrue,
+          reason: 'Expected to find $workflowPath in the project.',
+        );
+        final content = file.readAsStringSync();
+        final versions = versionsMatching(flutterVersionPattern, content);
+        expect(
+          versions,
+          isNotEmpty,
+          reason:
+              'Expected $workflowPath to declare at least one Flutter '
+              'version.',
+        );
+        for (final version in versions) {
+          expect(
+            version,
+            _isFlutter344ReleaseLine(flutterReleaseLine),
+            reason:
+                'Expected every Flutter toolchain declared in '
+                '$workflowPath to use the Flutter 3.44 release line, but '
+                'found "$version".',
+          );
+        }
+      }
+    });
