--- /dev/null
+++ b/test/helpers/mock_generator_builder.dart
@@ -0,0 +1,62 @@
+import 'dart:async';
+import 'dart:io';
+
+import 'package:mason/mason.dart';
+import 'package:mocktail/mocktail.dart';
+
+/// A mockable stand-in for a `MasonGeneratorFromBundle` builder function.
+class MockGeneratorBuilder extends Mock {
+  Future<MasonGenerator> call(MasonBundle bundle) =>
+      super.noSuchMethod(
+            Invocation.method(#call, [bundle]),
+          )
+          as Future<MasonGenerator>;
+}
+
+/// A fake [MasonBundle] so `any()` can be used with [MockGeneratorBuilder].
+class FakeMasonBundle extends Fake implements MasonBundle {}
+
+/// A lightweight [MasonGenerator] that renders a minimal `pubspec.yaml`
+/// reflecting the `workspace` template variable, without loading any hook
+/// packages or rendering the full scaffold bundles.
+///
+/// It exists so tests can assert the observable generated output of the
+/// workspace option without running the real (process-spawning) hooks.
+class WorkspaceTestGenerator extends MasonGenerator {
+  /// Creates a [WorkspaceTestGenerator].
+  WorkspaceTestGenerator()
+    : super(
+        'very_good_workspace_test',
+        'A fake generator used to exercise workspace-mode generation.',
+      );
+
+  @override
+  Future<List<GeneratedFile>> generate(
+    GeneratorTarget target, {
+    Map<String, dynamic> vars = const <String, dynamic>{},
+    FileConflictResolution? fileConflictResolution,
+    Logger? logger,
+  }) async {
+    final workspace = vars['workspace'] == true;
+    final buffer = StringBuffer()
+      ..writeln('name: ${vars['project_name'] ?? 'example'}')
+      ..writeln('description: ${vars['description'] ?? ''}')
+      ..writeln('version: 0.1.0+1')
+      ..writeln()
+      ..writeln('environment:')
+      ..writeln('  sdk: ^3.12.0')
+      ..writeln();
+    if (workspace) {
+      buffer
+        ..writeln('resolution: workspace')
+        ..writeln();
+    }
+
+    final directory = (target as DirectoryGeneratorTarget).dir
+      ..createSync(recursive: true);
+    final file = File('${directory.path}/pubspec.yaml')
+      ..writeAsStringSync(buffer.toString());
+
+    return [GeneratedFile.created(path: file.path)];
+  }
+}
