// inside her ring, so she should keep seeing him.
const east = SPAWN + ZONE + 8;
const ticksBefore = bob.ticks;
await bob.walkTo(east);
await sleep(4000);

console.log(`\nBob crossed into zone ${zoneOf(bob.x)}; Ada is in ${zoneOf(ada.x)} -- 1 apart, inside view_radius`);
check("Bob still receives world.tick", bob.ticks > ticksBefore + 5,
  `${ticksBefore} -> ${bob.ticks}`);
check("Bob sees his own entity", bob.entities.has(bob.playerId),
  `holds ${bob.entities.size} entities`);
check("Ada still sees Bob", ada.entities.has(bob.playerId));

// Cara follows Bob into the same zone.
await cara.walkTo(east);
await sleep(4000);
console.log(`\nCara walked into zone ${zoneOf(cara.x)} too, standing next to Bob`);
check("Cara sees Bob", cara.entities.has(bob.playerId));
check("Cara sees herself", cara.entities.has(cara.playerId));
check("Bob sees Cara", bob.entities.has(cara.playerId));
console.log(`     entities held -- Bob: ${bob.entities.size}, Cara: ${cara.entities.size}`);

// Does it ever come back on its own? Note Bob keeps receiving ticks the whole
// time -- he is still subscribed to the zone he came from, where Ada is. It is
// the zone he walked into that delivers nothing.
const stuck = bob.ticks;
await sleep(15000);
check("Bob's own entity comes back after 15 s of standing there",
  bob.entities.has(bob.playerId),
  `ticks ${stuck} -> ${bob.ticks} (still flowing), entities ${bob.entities.size}`);

// Walking back into the spawn zone.
await bob.walkTo(SPAWN + 4);
await sleep(4000);
check("walking back into the spawn zone restores him", bob.entities.has(bob.playerId),
  `entities ${bob.entities.size}, ticks ${bob.ticks}`);

clearInterval(beat);
ada.ws.close(); bob.ws.close(); cara.ws.close();
console.log(`\n${failures === 0 ? "no blackout" : failures + " check(s) failed -- players go dark on a zone crossing"}`);
process.exit(failures === 0 ? 0 : 1);
```

