diff --git a/yaes-http/server/src/test/scala/in/rcard/yaes/http/server/DecodingErrorRedesignSpec.scala b/yaes-http/server/src/test/scala/in/rcard/yaes/http/server/DecodingErrorRedesignSpec.scala
