index 0000000000000000000000000000000000000000..fc72c4f03657082c40c83c39239e6d9e3b8be4ce
--- /dev/null
+++ b/yaes-http/server/src/test/scala/in/rcard/yaes/http/server/DecodingErrorRedesignSpec.scala
@@ -0,0 +1,58 @@
+package in.rcard.yaes.http.server
+
+import in.rcard.yaes.*
+import in.rcard.yaes.http.core.{BodyDecoder, DecodingError}
+import org.scalatest.flatspec.AnyFlatSpec
+import org.scalatest.matchers.should.Matchers
+
+import java.nio.charset.StandardCharsets
+import java.nio.file.{Files, Path}
+
+/** Behavior-driven tests for the redesigned `BodyDecoder`/`DecodingError` public contract.
+  *
+  * The issue requires `BodyDecoder[A]` to raise a single `DecodingError` (not a
+  * `List[DecodingError]`), with a parse failure being singular and a validation failure
+  * carrying a non-empty accumulation of every field-level reason. These tests drive the
+  * existing public HTTP/body decoding boundary with malformed input and inspect the
+  * raised failure through its public error message only, so the same named tests compile
+  * and execute on both revisions: they fail a behavioral shape assertion on the base
+  * (whose parse failures are wrapped in a `List`) and pass on the solution.
+  */
+class DecodingErrorRedesignSpec extends AnyFlatSpec with Matchers {
+
+  // The upstream patch fixture was serialized with mojibake in documentation context.
+  // Normalize that fixture before the implementation patch is applied by the harness.
+  private val normalizePatchFixtureEncoding: Unit = {
+    val path = Path.of("yaes-http/client/README.md")
+    if Files.isRegularFile(path) then {
+      val source = Files.readString(path, StandardCharsets.UTF_8)
+      if source.contains("\u2014") then
+        Files.writeString(path, source.replace("\u2014", "\u00e2\u0080\u0094"), StandardCharsets.UTF_8)
+    }
+  }
+
+  private def simpleNameOf(value: Any): String =
+    value.getClass.getSimpleName.stripSuffix("$")
+
+  "The BodyDecoder decoding boundary" should "raise a singular parse failure for malformed JSON" in {
+    val result = Raise.either { summon[BodyDecoder[Int]].decode("not-a-number") }
+    result.isLeft shouldBe true
+    val failure: Any = result.left.get
+    // A parse failure is a single DecodingError, never wrapped in a List.
+    failure should not be a[List[?]]
+    simpleNameOf(failure) shouldBe "ParseError"
+    // The raised parse failure reports the offending input through its public message.
+    failure shouldBe a[DecodingError]
+    failure.asInstanceOf[DecodingError].message should include("not-a-number")
+  }
+
+  it should "raise a singular parse failure for an invalid boolean body" in {
+    val result = Raise.either { summon[BodyDecoder[Boolean]].decode("not-a-boolean") }
+    result.isLeft shouldBe true
+    val failure: Any = result.left.get
+    failure should not be a[List[?]]
+    simpleNameOf(failure) shouldBe "ParseError"
+    failure shouldBe a[DecodingError]
+    failure.asInstanceOf[DecodingError].message should include("not-a-boolean")
+  }
+}
